function normalizePath(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const trimmed = value.trim().replace(/\\/g, '/');
  return trimmed ? trimmed : null;
}

function recordEvidenceFromToolExecution(
  state: ReviewEvidenceState,
  action: Extract<ReviewAgentAction, { type: 'tool' }>,
  toolOutput: unknown,
  changedPaths: Set<string>
): void {
  if (action.tool === 'diff_summary') {
    state.diffSummaryUsed = true;
    return;
  }

  if (action.tool === 'read_file') {
    const readPath = normalizePath(action.args.path);
    if (readPath) {
      if (changedPaths.has(readPath)) {
        state.readChangedPaths.add(readPath);
      } else {
        state.readCrossFilePaths.add(readPath);
      }
    }
    return;
  }

  if (action.tool === 'read_batch') {
    const files = Array.isArray(asRecord(toolOutput).files) ? (asRecord(toolOutput).files as unknown[]) : [];
    for (const file of files) {
      const readPath = normalizePath(asRecord(file).path);
      if (!readPath) {
        continue;
      }
      if (changedPaths.has(readPath)) {
        state.readChangedPaths.add(readPath);
      } else {
        state.readCrossFilePaths.add(readPath);
      }
    }
    return;
  }

  if (action.tool === 'search_code' || action.tool === 'trace_symbol' || action.tool === 'trace_terms' || action.tool === 'trace_branches') {
    state.searchUsed = true;
    const matches = Array.isArray(asRecord(toolOutput).matches) ? (asRecord(toolOutput).matches as unknown[]) : [];
    state.searchMatchedChangedPath = matches.some((match) => {
      const matchPath = normalizePath(asRecord(match).path);
      return Boolean(matchPath && changedPaths.has(matchPath));
    });
  }
}

function collectMissingEvidenceRequirements(input: {
  evidence: ReviewEvidenceState;
  changedPaths: string[];
}): string[] {
  const missing: string[] = [];
  const sensitiveChangedPaths = input.changedPaths.filter((path) => isSensitiveChangedPath(path));

  if (input.changedPaths.length > 0 && !input.evidence.diffSummaryUsed) {
    missing.push('Run diff_summary at least once before completing analysis.');
  }

  const requiredReadCoverage =
    input.changedPaths.length <= MAX_DIRECT_CHANGED_FILE_COVERAGE_REQUIREMENT
      ? input.changedPaths.length
      : Math.min(MIN_DIRECT_CHANGED_FILE_COVERAGE, input.changedPaths.length);
  if (input.evidence.readChangedPaths.size < requiredReadCoverage) {
    missing.push(
      `Read at least ${requiredReadCoverage} changed file(s) directly with read_file (currently ${input.evidence.readChangedPaths.size}).`
    );
  }

  const missingSensitivePaths = sensitiveChangedPaths.filter((path) => !input.evidence.readChangedPaths.has(path));
  if (missingSensitivePaths.length > 0) {
    missing.push(`Read sensitive changed file(s) directly: ${missingSensitivePaths.join(', ')}.`);
  }

  if (sensitiveChangedPaths.length > 0 && input.evidence.readCrossFilePaths.size === 0) {
    missing.push('Read at least one non-changed file that is referenced or matched while investigating sensitive changed paths.');
  }

  if (input.changedPaths.length > 0 && !input.evidence.searchUsed) {
    missing.push('Run search_code at least once before completing analysis.');
  }

  return missing;
}

function mentionsSensitivePath(summary: string, sensitiveChangedPaths: string[]): boolean {
  const loweredSummary = summary.toLowerCase();
  return sensitiveChangedPaths.some((path) => {
    const fileName = path.split('/').pop() ?? path;
    return loweredSummary.includes(path.toLowerCase()) || loweredSummary.includes(fileName.toLowerCase());
  });
}

function classifyRequiredSensitiveScenarios(paths: string[]): Array<'invalidInput' | 'overlappingExecution' | 'terminalState' | 'crossFileGuards'> {
  const required = new Set<'invalidInput' | 'overlappingExecution' | 'terminalState' | 'crossFileGuards'>();
  for (const path of paths) {
    if (/(?:auth|token|credential)/i.test(path)) {
      required.add('invalidInput');
    }
    if (/(?:recovery|retry|queue|status|state|workflow)/i.test(path)) {
      required.add('overlappingExecution');
      required.add('terminalState');
      required.add('crossFileGuards');
    }
  }
  return Array.from(required);
}

function findingMentionsScenario(
  finding: ReviewFinding,
  scenario: 'invalidInput' | 'overlappingExecution' | 'terminalState' | 'crossFileGuards'
): boolean {
  const haystack = `${finding.description}\n${finding.failingScenario ?? ''}\n${finding.evidence ?? ''}\n${finding.guardGap ?? ''}`.toLowerCase();
  switch (scenario) {
    case 'invalidInput':
      return /invalid|malformed|token|credential|auth|input/.test(haystack);
    case 'overlappingExecution':
      return /overlap|concurrent|in-flight|running|duplicate work|stale|replacement/.test(haystack);
    case 'terminalState':
      return /terminal|queued|failed|succeeded|immutable|overwrite final|downgrade/.test(haystack);
    case 'crossFileGuards':
      return /guard|validation|finaliz|cross-file|downstream|write/.test(haystack);
  }
}

