interface DeterministicSearchQuery {
  query: string;
  sourcePath: string;
}

interface DeterministicTraceTermsPlan {
  terms: string[];
  sourcePath: string;
}

function maybeAddDeterministicSearchQuery(
  queries: DeterministicSearchQuery[],
  seen: Set<string>,
  candidate: string,
  sourcePath: string
): void {
  const tempQueries: string[] = [];
  const beforeSize = seen.size;
  maybeAddSearchQuery(tempQueries, seen, candidate);
  if (seen.size > beforeSize && tempQueries.length > 0) {
    queries.push({ query: tempQueries[0], sourcePath });
  }
}

function extractDeterministicSearchQueries(changedFiles: ReviewContext['retrieval']['changedFiles']): DeterministicSearchQuery[] {
  const queries: DeterministicSearchQuery[] = [];
  const seen = new Set<string>();
  const sensitiveFiles = changedFiles.filter((file) => isSensitiveChangedPath(file.path));
  for (const file of sensitiveFiles) {
    const importMatches = file.content.matchAll(/\bimport\s+(?:type\s+)?(?:\{([^}]+)\}|([A-Za-z_][A-Za-z0-9_]*))/g);
    for (const match of importMatches) {
      const importedBlock = match[1] ?? match[2] ?? '';
      for (const item of importedBlock.split(',')) {
        const cleaned = item.replace(/\bas\b.+$/i, '').trim();
        maybeAddDeterministicSearchQuery(queries, seen, cleaned, file.path);
        if (queries.length >= MAX_DETERMINISTIC_SEARCH_QUERIES) {
          return queries;
        }
      }
    }

    const callMatches = file.content.matchAll(/\b([A-Za-z_][A-Za-z0-9_]{3,})\s*\(/g);
    for (const match of callMatches) {
      maybeAddDeterministicSearchQuery(queries, seen, match[1] ?? '', file.path);
      if (queries.length >= MAX_DETERMINISTIC_SEARCH_QUERIES) {
        return queries;
      }
    }

    const stem = pathStem(file.path);
    if (stem) {
      maybeAddDeterministicSearchQuery(queries, seen, stem, file.path);
      if (queries.length >= MAX_DETERMINISTIC_SEARCH_QUERIES) {
        return queries;
      }
    }
  }

  if (queries.length === 0) {
    const fallbackStem = changedFiles.map((file) => pathStem(file.path)).find(Boolean);
    if (fallbackStem) {
      maybeAddDeterministicSearchQuery(queries, seen, fallbackStem, changedFiles[0]?.path ?? '.');
    }
  }

  return queries.slice(0, MAX_DETERMINISTIC_SEARCH_QUERIES);
}

export function extractDeterministicSearchQueriesForTests(
  changedFiles: ReviewContext['retrieval']['changedFiles']
): string[] {
  return extractDeterministicSearchQueries(changedFiles).map((entry) => entry.query);
}

function extractDeterministicTraceTerms(changedFiles: ReviewContext['retrieval']['changedFiles']): DeterministicTraceTermsPlan | null {
  const sensitiveFiles = changedFiles.filter((file) => isSensitiveChangedPath(file.path));
  if (sensitiveFiles.length === 0) {
    return null;
  }

  const terms: string[] = [];
  const seen = new Set<string>();
  const priorityKeyword = /(status|state|queue|retry|recover|fail|error|timeout|running|queued|pending|succeed|success|complete|token|auth|credential)/i;

  for (const file of sensitiveFiles) {
    const stringLiteralMatches = file.content.matchAll(/['"`]([A-Za-z0-9_-]{4,40})['"`]/g);
    for (const match of stringLiteralMatches) {
      const candidate = match[1] ?? '';
      if (!priorityKeyword.test(candidate)) {
        continue;
      }
      maybeAddSearchQuery(terms, seen, candidate);
      if (terms.length >= MAX_DETERMINISTIC_TRACE_TERMS) {
        return { terms, sourcePath: file.path };
      }
    }

    const identifierMatches = file.content.matchAll(/\b([A-Za-z_][A-Za-z0-9_]{3,})\b/g);
    for (const match of identifierMatches) {
      const candidate = match[1] ?? '';
      if (!priorityKeyword.test(candidate)) {
        continue;
      }
      maybeAddSearchQuery(terms, seen, candidate);
      if (terms.length >= MAX_DETERMINISTIC_TRACE_TERMS) {
        return { terms, sourcePath: file.path };
      }
    }
  }

  return terms.length > 0 ? { terms, sourcePath: sensitiveFiles[0]?.path ?? changedFiles[0]?.path ?? '.' } : null;
}

export function extractDeterministicTraceTermsForTests(
  changedFiles: ReviewContext['retrieval']['changedFiles']
): string[] {
  return extractDeterministicTraceTerms(changedFiles)?.terms ?? [];
}

