    type: 'final',
    summary: buildReviewFinalSummary(),
  };
}

function nextWorkspaceTaskAction(history: AgentHistoryEntry[]): AgentAction {
  if (!hasToolOutput(history, 'list_files')) {
    return { type: 'tool', tool: 'list_files', args: { path: '.' } };
  }
  if (!hasToolOutput(history, 'read_file')) {
    return { type: 'tool', tool: 'read_file', args: { path: 'README.md', maxBytes: 2000 } };
  }
  return { type: 'final', summary: 'Completed by Nimbus agent endpoint.' };
}

export function nextAgentAction(request: AgentRequest): AgentAction {
  const prompt = typeof request.prompt === 'string' ? request.prompt : '';
  const history = Array.isArray(request.history) ? request.history : [];
  if (isReviewPrompt(prompt)) {
    return nextReviewAction(history);
  }
  return nextWorkspaceTaskAction(history);
}

export async function nextAgentActionWithInference(
  request: AgentRequest,
  env: AgentEnv,
  options?: { openrouterApiKey?: string | null }
): Promise<AgentAction> {
  const prompt = typeof request.prompt === 'string' ? request.prompt : '';
  const history = Array.isArray(request.history) ? request.history : [];

  if (!isReviewPrompt(prompt)) {
    return nextWorkspaceTaskAction(history);
  }

  const requestApiKey = typeof options?.openrouterApiKey === 'string' ? options.openrouterApiKey.trim() : '';
  const envApiKey = (env.OPENROUTER_API_KEY ?? '').trim();
  const apiKey = requestApiKey || envApiKey;
  if (!apiKey) {
    throw new AgentEndpointError('missing_openrouter_api_key', 500, {
      message: 'OPENROUTER_API_KEY is required',
    });
  }

  const model = resolveOpenRouterModel(request.model, env.DEFAULT_MODEL);
  const httpReferer = typeof env.OPENROUTER_HTTP_REFERER === 'string' ? env.OPENROUTER_HTTP_REFERER.trim() : '';
  const xTitle = typeof env.OPENROUTER_X_TITLE === 'string' ? env.OPENROUTER_X_TITLE.trim() : '';
  const content = await callOpenRouter({
    apiKey,
    model,
    prompt,
    ...(httpReferer ? { httpReferer } : {}),
    ...(xTitle ? { xTitle } : {}),
  });
  let parsed: unknown;
  try {
    parsed = JSON.parse(stripCodeFences(content));
  } catch {
    const candidate = extractJsonObjectCandidate(content);
    if (!candidate) {
      throw new AgentEndpointError('invalid_model_output', 422, {
        errors: [{ path: '$', message: 'model response was not valid JSON' }],
        preview: content.slice(0, 500),
      });
    }
    try {
      parsed = JSON.parse(candidate);
    } catch {
      throw new AgentEndpointError('invalid_model_output', 422, {
        errors: [{ path: '$', message: 'model response was not valid JSON' }],
        preview: content.slice(0, 500),
      });
    }
  }

import {
  AgentEndpointError,
  nextAgentActionWithInference,
  type AgentEnv,
  type AgentRequest,
} from './lib/agent.js';

const SENSITIVE_PATTERNS: RegExp[] = [
  /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
  /\bsk-[A-Za-z0-9_-]+\b/gi,
  /\bnmb_live_[A-Za-z0-9_-]+\b/gi,
];

const GENERIC_UPSTREAM_ERROR_MESSAGE = 'upstream error';

function readBearerToken(value: string | null): string | null {
  if (!value) {
    return null;
  }
  const match = value.match(/^Bearer\s+(.+)$/i);
  if (!match) {
    return null;
  }
  const token = match[1]?.trim();
  return token ? token : null;
}

function hasSensitivePattern(value: string): boolean {
  return SENSITIVE_PATTERNS.some((pattern) => {
    pattern.lastIndex = 0;
    return pattern.test(value);
  });
}

function sanitizeErrorMessage(rawMessage: string): string {
  const trimmed = rawMessage.trim();
  if (!trimmed) {
    return GENERIC_UPSTREAM_ERROR_MESSAGE;
  }

  let sanitized = trimmed;
  for (const pattern of SENSITIVE_PATTERNS) {
    pattern.lastIndex = 0;
    sanitized = sanitized.replace(pattern, '[REDACTED]');
  }

  sanitized = sanitized.replace(/\s+/g, ' ').trim();
  if (!sanitized || sanitized === '[REDACTED]' || hasSensitivePattern(sanitized)) {
    return GENERIC_UPSTREAM_ERROR_MESSAGE;
  }

  return sanitized;
}

function sanitizeErrorDetails(details: Record<string, unknown> | undefined): Record<string, unknown> | null {
  if (!details) {
    return null;
  }

  const message = details.message;
  if (typeof message !== 'string') {
    return details;
  }

  return {
    ...details,
    message: sanitizeErrorMessage(message),
  };
}

export default {
  async fetch(request: Request, env: AgentEnv): Promise<Response> {
    if (request.method !== 'POST') {
      return new Response(JSON.stringify({ error: 'method_not_allowed' }), {
        status: 405,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const expectedAuthToken = (env.AGENT_SDK_AUTH_TOKEN ?? '').trim();
    const providedAuthToken = readBearerToken(request.headers.get('Authorization'));
    if (!expectedAuthToken || !providedAuthToken || providedAuthToken !== expectedAuthToken) {
      return new Response(JSON.stringify({ error: 'unauthorized' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    let payload: AgentRequest;
    try {
      payload = (await request.json()) as AgentRequest;
    } catch {
      return new Response(JSON.stringify({ error: 'invalid_json' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    try {
      const openrouterApiKeyHeader = request.headers.get('X-Openrouter-Api-Key');
      const action = await nextAgentActionWithInference(payload, env, {
        openrouterApiKey: typeof openrouterApiKeyHeader === 'string' ? openrouterApiKeyHeader : null,
      });
      return new Response(JSON.stringify({ action }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    } catch (error) {
      if (error instanceof AgentEndpointError) {
        const safeDetails = sanitizeErrorDetails(error.details);
        return new Response(
          JSON.stringify({
            error: error.code,
            details: safeDetails,
          }),
          {
            status: error.status,
            headers: { 'Content-Type': 'application/json' },
          }
        );
      }

      return new Response(
        JSON.stringify({
          error: 'internal_error',
          details: error instanceof Error ? { message: sanitizeErrorMessage(error.message) } : null,
        }),
        {
          status: 500,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
  },
};

import { execFileSync } from 'child_process';
import { readFileSync, watch, type FSWatcher } from 'fs';
import { join } from 'path';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { resolveStudioNewReviewPreflight, type StudioNewReviewPreflightResult } from './studio-create.js';

interface PreflightCacheState {
  headSha: string | null;
  policyMode: 'auto' | 'review' | null;
  lastCheckpoints: 1 | 2 | 3 | null;
  refreshedAtMs: number | null;
  value: StudioNewReviewPreflightResult | null;
}

const PREFLIGHT_CACHE_MAX_AGE_MS = 8_000;

let cache: PreflightCacheState = {
  headSha: null,
  policyMode: null,
  lastCheckpoints: null,
  refreshedAtMs: null,
  value: null,
};
const inFlightByKey = new Map<string, Promise<StudioNewReviewPreflightResult>>();
let headWatcher: FSWatcher | null = null;
let refWatcher: FSWatcher | null = null;
let studioPreferencesWatcher: FSWatcher | null = null;
let refreshDebounceTimer: NodeJS.Timeout | null = null;
let resolveStudioNewReviewPreflightForCache: typeof resolveStudioNewReviewPreflight = resolveStudioNewReviewPreflight;

function resolveHeadSha(repoRoot: string): string | null {
  try {
    return new GitRepo(repoRoot).resolveCommitSha('HEAD');
  } catch {
    return null;
  }
}

function resolveStudioPolicyMode(repoRoot: string): 'auto' | 'review' | null {
  try {
    const raw = JSON.parse(readFileSync(join(repoRoot, '.nimbus', 'studio.json'), 'utf8')) as {
      policyMode?: unknown;
    };
    if (raw.policyMode === 'auto' || raw.policyMode === 'review') {
      return raw.policyMode;
    }
    return null;
  } catch {
    return null;
  }
}

async function refreshPreflight(repoRoot: string, lastCheckpoints: 1 | 2 | 3): Promise<StudioNewReviewPreflightResult> {
  const inFlightKey = `${repoRoot}:${lastCheckpoints}`;
  const existing = inFlightByKey.get(inFlightKey);
  if (existing) {
    return existing;
  }
  const pending = (async () => {
    const result = await resolveStudioNewReviewPreflightForCache({ repoRoot, lastCheckpoints });
    cache = {
      headSha: resolveHeadSha(repoRoot),
      policyMode: resolveStudioPolicyMode(repoRoot),
      lastCheckpoints,
      refreshedAtMs: Date.now(),
      value: result,
    };
    return result;
  })();
  inFlightByKey.set(inFlightKey, pending);
  try {
    return await pending;
  } finally {
    if (inFlightByKey.get(inFlightKey) === pending) {
      inFlightByKey.delete(inFlightKey);
    }
  }
}

function resolveGitDir(repoRoot: string): string | null {
  try {
    const output = execFileSync('git', ['rev-parse', '--git-dir'], {
      cwd: repoRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .toString()
      .trim();
    if (!output) {
      return null;
    }
    return output.startsWith('/') ? output : join(repoRoot, output);
  } catch {
    return null;
  }
}

function resolveHeadRef(gitDir: string): string | null {
  try {
    const output = readFileSync(join(gitDir, 'HEAD'), 'utf8').trim();
    if (!output.startsWith('ref:')) {
      return null;
    }
    const headRef = output.slice(4).trim();
    return headRef || null;
  } catch {
    return null;
  }
}

function queueRefresh(repoRoot: string): void {
  if (refreshDebounceTimer) {
    clearTimeout(refreshDebounceTimer);
  }
  refreshDebounceTimer = setTimeout(() => {
    refreshDebounceTimer = null;
    void refreshPreflight(repoRoot, 2).catch(() => undefined);
  }, 250);
  if (typeof refreshDebounceTimer.unref === 'function') {
    refreshDebounceTimer.unref();
  }
}

function closeWatchers(): void {
  if (headWatcher) {
    headWatcher.close();
    headWatcher = null;
  }
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  if (studioPreferencesWatcher) {
    studioPreferencesWatcher.close();
    studioPreferencesWatcher = null;
  }
}

function watchHeadRefPath(repoRoot: string, gitDir: string): void {
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  const headRef = resolveHeadRef(gitDir);
  if (!headRef || !headRef.startsWith('refs/')) {
    return;
  }
  const headRefPath = join(gitDir, ...headRef.split('/'));
  try {
    refWatcher = watch(headRefPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    refWatcher = null;
  }
}

export async function getStudioNewReviewPreflightCached(options?: {
  repoRoot?: string;
  lastCheckpoints?: 1 | 2 | 3;
}): Promise<StudioNewReviewPreflightResult> {
  const repoRoot = options?.repoRoot ?? process.cwd();
  const lastCheckpoints = options?.lastCheckpoints ?? 2;
  const headSha = resolveHeadSha(repoRoot);
  const policyMode = resolveStudioPolicyMode(repoRoot);
  const cacheIsFresh =
    typeof cache.refreshedAtMs === 'number' && Date.now() - cache.refreshedAtMs <= PREFLIGHT_CACHE_MAX_AGE_MS;
  if (
    cache.value &&
    cacheIsFresh &&
    cache.headSha &&
    headSha &&
    cache.headSha === headSha &&
    cache.policyMode === policyMode &&
    cache.lastCheckpoints === lastCheckpoints
  ) {
    return cache.value;
  }
  return refreshPreflight(repoRoot, lastCheckpoints);
}

export function startStudioPreflightBackgroundPolling(options?: {
  repoRoot?: string;
}): void {
  if (headWatcher) {
    return;
  }
  const repoRoot = options?.repoRoot ?? process.cwd();
  const gitDir = resolveGitDir(repoRoot);

  void refreshPreflight(repoRoot, 2).catch(() => undefined);
  if (!gitDir) {
    return;
  }

  const headPath = join(gitDir, 'HEAD');
  try {
    headWatcher = watch(headPath, () => {
      watchHeadRefPath(repoRoot, gitDir);
      queueRefresh(repoRoot);
    });
  } catch {
    headWatcher = null;
    return;
  }
  watchHeadRefPath(repoRoot, gitDir);
  const studioPreferencesPath = join(repoRoot, '.nimbus', 'studio.json');
  try {
    studioPreferencesWatcher = watch(studioPreferencesPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    studioPreferencesWatcher = null;
  }
}

