 45	/**
 46	 * Claims, executes, persists, and finalizes one review run.
 47	 * This is the main orchestration boundary for review execution and retry scheduling.
 48	 */
 49	export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
 50	  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
 51	  if (!claimed) {
 52	    const existing = await getReviewRun(env.DB, reviewId);
 53	    if (existing?.status === 'running') {
 54	      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
 55	    }
 56	    return;
 57	  }
 58	
 59	  let review: ReviewRunResponse | null = null;
 60	  try {
 61	    review = await getReviewRun(env.DB, reviewId);
 62	    if (!review) {
 63	      return;
 64	    }
 65	
 66	    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
 67	    if (!payload) {
 68	      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
 69	        errorCode: 'review_not_found',
 70	        errorMessage: 'Review request payload no longer exists',
 71	      });
 72	      await appendReviewEvent(env.DB, {
 73	        reviewId,
 74	        eventType: 'review_failed',
 75	        payload: {
 76	          code: 'review_not_found',
 77	          message: 'Review request payload no longer exists',
 78	        },
 79	      });
 80	      return;
 81	    }
 82	
 83	    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
 84	    const report = await executeReviewRun(env, review, payload, reviewContext, options);
 85	    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
 86	    if (!latest) {
 87	      return;
 88	    }
 89	    await finalizeSuccessfulReview(env, reviewId, payload, report);
 90	  } catch (error) {
 91	    const message = formatReviewAnalysisError(error, {
 92	      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
 93	    });
 94	    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
 95	    if (!latest) {
 96	      return;
 97	    }
 98	    const attemptCount = latest?.attemptCount ?? review?.attemptCount ?? 0;
 99	
100	    const allowRetryScheduling = options?.allowRetryScheduling !== false;
101	    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
102	      await scheduleReviewRetry(env, reviewId, {
103	        attemptCount,
104	        message,
105	        reason: message.slice(0, 500),
106	        throwMessage: 'Review transient failure; retry requested',
107	      });
108	    }
109	
110	    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
111	    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
112	    await finalizeFailedReview(env, reviewId, {
113	      errorCode: finalErrorCode,
114	      message,
115	      contextAssemblyErrorCode,
116	    });
117	  }
118	}
