 20	function parseTimeoutMs(value: string | undefined, fallback: number): number {
 21	  if (typeof value !== 'string') {
 22	    return fallback;
 23	  }
 24	  const parsed = Number.parseInt(value, 10);
 25	  if (!Number.isFinite(parsed) || parsed <= 0) {
