 46	export async function scheduleReviewRetry(
 47	  env: Env,
 48	  reviewId: string,
 49	  input: {
 50	    attemptCount: number;
 51	    message: string;
 52	    reason: string;
 53	    extraPayload?: Record<string, unknown>;
 54	    throwMessage?: string;
 55	  }
 56	): Promise<never> {
 57	  await replaceReviewFindings(env.DB, reviewId, []);
 58	  await updateReviewRunStatus(env.DB, reviewId, 'queued', {
 59	    report: null,
 60	    markdownSummary: null,
 61	    startedAt: null,
 62	    finishedAt: null,
 63	    errorCode: 'retry_scheduled',
 64	    errorMessage: input.message,
 65	  });
 66	  await appendReviewEvent(env.DB, {
 67	    reviewId,
 68	    eventType: 'review_retry_scheduled',
 69	    payload: {
 70	      attemptCount: input.attemptCount,
 71	      maxRetries: REVIEW_MAX_RETRIES,
 72	      reason: input.reason,
 73	      ...(input.extraPayload ?? {}),
 74	    },
 75	  });
 76	  throw new QueueRetryError(input.throwMessage ?? 'Review retry requested');
