import type { Env, ReviewReport, ReviewRunResponse } from '../types.js';
import {
  appendReviewEvent,
  claimReviewRunForExecution,
  getReviewRun,
  getReviewRunRequestPayload,
  updateReviewRunStatus,
} from './db.js';
import { formatReviewAnalysisError } from './review-analysis.js';
import { ReviewContextAssemblyError } from './review-runner/cochange.js';
import { readOptionalString } from './review-runner/context-helpers.js';
import { assembleReviewContextBootstrap } from './review-runner/context.js';
import { executeReviewRun } from './review-runner/execution.js';
import { finalizeFailedReview, finalizeSuccessfulReview } from './review-runner/finalization.js';
import { intentSummaryFromApprovedPolicy, runIntentSummarizationPrePass, summarizeReviewIntentPolicy } from './review-runner/intent-summary.js';
import {
  finalizeInlineRetryExhaustion,
  handleUnclaimedReviewRun,
  QueueRetryError,
  scheduleReviewRetry,
  shouldRetryReviewError,
} from './review-runner/retry.js';
import type { ReviewRunExecutionOptions } from './review-runner/shared.js';

export {
  intentSummaryFromApprovedPolicy,
  runIntentSummarizationPrePass,
  summarizeReviewIntentPolicy,
} from './review-runner/intent-summary.js';
export { shouldRetryReviewError } from './review-runner/retry.js';

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function isManuallyFailedReview(review: ReviewRunResponse | null): boolean {
  return review?.status === 'failed' && review.error?.code === 'review_execution_aborted';
}

async function loadLatestReviewUnlessManuallyFailed(env: Env, reviewId: string): Promise<ReviewRunResponse | null> {
  const latest = await getReviewRun(env.DB, reviewId);
  return isManuallyFailedReview(latest) ? null : latest;
}

/**
 * Claims, executes, persists, and finalizes one review run.
 * This is the main orchestration boundary for review execution and retry scheduling.
 */
export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
  if (!claimed) {
    const existing = await getReviewRun(env.DB, reviewId);
    if (existing?.status === 'running') {
      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
    }
    return;
  }

  let review: ReviewRunResponse | null = null;
  try {
    review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return;
    }

    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
    if (!payload) {
      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
        errorCode: 'review_not_found',
        errorMessage: 'Review request payload no longer exists',
      });
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_failed',
        payload: {
          code: 'review_not_found',
          message: 'Review request payload no longer exists',
        },
      });
      return;
    }

    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
    const report = await executeReviewRun(env, review, payload, reviewContext, options);
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    await finalizeSuccessfulReview(env, reviewId, payload, report);
  } catch (error) {
    const message = formatReviewAnalysisError(error, {
      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    const attemptCount = latest?.attemptCount ?? review?.attemptCount ?? 0;

    const allowRetryScheduling = options?.allowRetryScheduling !== false;
    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
      await scheduleReviewRetry(env, reviewId, {
        attemptCount,
        message,
        reason: message.slice(0, 500),
        throwMessage: 'Review transient failure; retry requested',
      });
    }

    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
    await finalizeFailedReview(env, reviewId, {
      errorCode: finalErrorCode,
      message,
      contextAssemblyErrorCode,
    });
  }
}

/**
 * Repeats inline review execution while the persisted state requests another retry cycle.
 */
export async function runReviewInlineWithRetries(
  env: Env,
  reviewId: string,
  maxCycles = 4,
  options?: ReviewRunExecutionOptions
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processReviewRun(env, reviewId, options);
    } catch {
      // Retry scheduling is inferred from persisted status.
    }

    const latest = await getReviewRun(env.DB, reviewId);
    if (!latest) {
      return;
    }
    if (latest.status !== 'queued') {
      return;
    }
    if (latest.error?.code !== 'retry_scheduled') {
      return;
    }
  }

  await finalizeInlineRetryExhaustion(env, reviewId);
}

import type { Env, ReviewRunStatus } from '../../types.js';
import {
  appendReviewEvent,
  getReviewRun,
  getReviewRunRequestPayload,
  replaceReviewFindings,
  updateReviewRunStatus,
} from '../../lib/db.js';
import { createReviewQueueMessage } from '../../lib/review-queue.js';
import { jsonResponse } from './shared.js';

const REVIEW_STALE_RUNNING_GRACE_MS = 60_000;
export const REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS = 120_000;

function parseTimeoutMs(value: string | undefined, fallback: number): number {
  if (typeof value !== 'string') {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }
  return parsed;
}

function parseMaxRetryCount(value: string | undefined, fallbackAttempts: number): number {
  const parsedAttempts = Number.parseInt(value ?? '', 10);
  const attempts = Number.isFinite(parsedAttempts) && parsedAttempts > 0 ? parsedAttempts : fallbackAttempts;
  return Math.max(0, attempts - 1);
}

function hasLocalCochangeProvenance(payload: unknown): boolean {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return false;
  }
  const record = payload as Record<string, unknown>;
  const provenance = record.provenance;
  if (!provenance || typeof provenance !== 'object' || Array.isArray(provenance)) {
    return false;
  }
  const localCochange = (provenance as Record<string, unknown>).localCochange;
  if (!localCochange || typeof localCochange !== 'object' || Array.isArray(localCochange)) {
    return false;
  }
  const candidate = localCochange as Record<string, unknown>;
  if (candidate.source !== 'local_git') {
    return false;
  }
  if (!Object.prototype.hasOwnProperty.call(candidate, 'relatedByChangedPath')) {
    return false;
  }
  const relatedByChangedPath = candidate.relatedByChangedPath;
  return Boolean(relatedByChangedPath !== null && typeof relatedByChangedPath === 'object' && !Array.isArray(relatedByChangedPath));
}

function isValidScopedGithubToken(value: string): boolean {
  const token = value.trim();
  if (!token) {
    return false;
  }
  return /^(ghp_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})$/.test(token);
}

export async function recoverStaleRunningReviewIfNeeded(
  env: Env,
  reviewId: string,
  review: { status: ReviewRunStatus; startedAt: string | null; updatedAt: string; createdAt: string; attemptCount: number },
  cochangeGithubToken?: string | null,
  openrouterApiKey?: string | null,
  options?: { markFailedWhenRetryUnavailable?: boolean; noAuthTerminalGraceMs?: number }
): Promise<void> {
  if (review.status !== 'running') {
    return;
  }
  const attemptTimeoutMs = parseTimeoutMs(env.ATTEMPT_TIMEOUT_MS, 600_000);
  const staleThresholdMs = attemptTimeoutMs + REVIEW_STALE_RUNNING_GRACE_MS;
  const startedMs = Date.parse(review.startedAt ?? review.updatedAt ?? review.createdAt);
  if (!Number.isFinite(startedMs)) {
    return;
  }
  const staleForMs = Date.now() - startedMs;
  if (staleForMs < staleThresholdMs) {
    return;
  }

  const maxRetries = parseMaxRetryCount(env.MAX_ATTEMPTS, 3);
  const requestPayload = await getReviewRunRequestPayload(env.DB, reviewId);
  const canRetryWithoutGithubToken = hasLocalCochangeProvenance(requestPayload);
  const rawScopedToken = typeof cochangeGithubToken === 'string' && cochangeGithubToken.trim() ? cochangeGithubToken.trim() : null;
  const scopedGithubToken = rawScopedToken && isValidScopedGithubToken(rawScopedToken) ? rawScopedToken : null;
  const hasInvalidScopedToken = Boolean(rawScopedToken) && !scopedGithubToken;
  if (review.attemptCount <= maxRetries && env.REVIEWS_QUEUE && (scopedGithubToken || canRetryWithoutGithubToken)) {
    await updateReviewRunStatus(env.DB, reviewId, 'queued', {
      report: null,
      markdownSummary: null,
      startedAt: null,
      finishedAt: null,
      errorCode: 'retry_scheduled',
      errorMessage: `Review execution stalled in running state for ${Math.floor(staleForMs / 1000)}s.`,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_retry_scheduled',
      payload: {
        attemptCount: review.attemptCount,
        maxRetries,
        reason: 'stale_running_timeout',
        staleForSeconds: Math.floor(staleForMs / 1000),
        authMode: scopedGithubToken ? 'scoped_request_token' : 'local_cochange_only',
      },
    });
    await env.REVIEWS_QUEUE.send(createReviewQueueMessage(reviewId, scopedGithubToken, openrouterApiKey));
    return;
  }

  if (options?.markFailedWhenRetryUnavailable === false) {
    const noAuthTerminalGraceMs =
      typeof options.noAuthTerminalGraceMs === 'number' && options.noAuthTerminalGraceMs >= 0
        ? options.noAuthTerminalGraceMs
        : REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS;
    if (staleForMs < staleThresholdMs + noAuthTerminalGraceMs) {
      return;
    }
