  }
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeToolValue(item));
  }
  if (value && typeof value === 'object') {
    return Object.entries(value as Record<string, unknown>).reduce<Record<string, unknown>>((result, [key, nested]) => {
      result[key] = sanitizeToolValue(nested);
      return result;
    }, {});
  }
  return value;
}

export function sanitizeToolContext(context: ReviewToolContext): ReviewToolContext {
  return {
    request: sanitizeToolValue(context.request) as Record<string, unknown>,
    result: sanitizeToolValue(context.result),
  };
}

export function buildToolHistoryLabel(action: Extract<ReviewAgentAction, { type: 'tool' }>): string {
  return `tool:${action.tool} ${JSON.stringify(action.args)}`;
}

function buildListFilesCommand(absolutePath: string, rootPath: string): string {
  return `python3 - ${shellQuote(absolutePath)} ${shellQuote(rootPath)} <<'PY'
import json
import os
import sys

path = sys.argv[1]
root = sys.argv[2]
root_real = os.path.realpath(root)
target = path if os.path.isabs(path) else os.path.join(root, path)
target_real = os.path.realpath(target)
if os.path.commonpath([root_real, target_real]) != root_real:
    print(json.dumps({'error':'path_escape'}))
    raise SystemExit(0)
if not os.path.exists(target_real):
    print(json.dumps({'error':'not_found'}))
    raise SystemExit(0)
if not os.path.isdir(target_real):
    print(json.dumps({'error':'not_directory'}))
    raise SystemExit(0)
entries = []
for name in sorted(os.listdir(target_real)):
    full = os.path.join(target_real, name)
    entries.append({'name': name, 'type': 'directory' if os.path.isdir(full) else 'file'})
print(json.dumps({'entries': entries[:200]}))
PY`;
}

function buildReadFileCommand(absolutePath: string, maxBytes: number, rootPath: string): string {
  return `python3 - ${shellQuote(absolutePath)} ${maxBytes} ${shellQuote(rootPath)} <<'PY'
import json
import os
import sys

path = sys.argv[1]
max_bytes = int(sys.argv[2])
root = sys.argv[3]
root_real = os.path.realpath(root)
target = path if os.path.isabs(path) else os.path.join(root, path)
target_real = os.path.realpath(target)
if os.path.commonpath([root_real, target_real]) != root_real:
    print(json.dumps({'error':'path_escape'}))
    raise SystemExit(0)
if not os.path.exists(target_real):
    print(json.dumps({'error':'not_found'}))
    raise SystemExit(0)
if not os.path.isfile(target_real):
    print(json.dumps({'error':'not_file'}))
    raise SystemExit(0)
with open(target_real, 'rb') as f:
    data = f.read(max_bytes + 1)
truncated = len(data) > max_bytes
if truncated:
    data = data[:max_bytes]
text = data.decode('utf-8', errors='replace')
print(json.dumps({'content': text, 'truncated': truncated, 'bytes': len(data)}))
PY`;
}

function buildSearchCodeCommand(input: {
  absolutePath: string;
  query: string;
  maxResults: number;
  maxBytesPerFile: number;
  rootPath: string;
  caseSensitive: boolean;
}): string {
  return `python3 - ${shellQuote(input.absolutePath)} ${shellQuote(input.query)} ${input.maxResults} ${input.maxBytesPerFile} ${shellQuote(
    input.rootPath
  )} ${input.caseSensitive ? '1' : '0'} <<'PY'
import json
import os
import sys

target_path = sys.argv[1]
query = sys.argv[2]
max_results = int(sys.argv[3])
max_bytes_per_file = int(sys.argv[4])
root = sys.argv[5]
case_sensitive = sys.argv[6] == '1'

root_real = os.path.realpath(root)
target_real = os.path.realpath(target_path)
if os.path.commonpath([root_real, target_real]) != root_real:
    print(json.dumps({'error': 'path_escape'}))
    raise SystemExit(0)
if not os.path.exists(target_real):
    print(json.dumps({'error': 'not_found'}))
    raise SystemExit(0)

skip_dirs = {'.git', 'node_modules', '.next', 'dist', 'build', '.cache'}
matches = []
scanned_files = 0

def process_file(path):
    global scanned_files
    scanned_files += 1
    try:
        with open(path, 'rb') as f:
            data = f.read(max_bytes_per_file)
        text = data.decode('utf-8', errors='replace')
    except Exception:
        return

    haystack = text if case_sensitive else text.lower()
    needle = query if case_sensitive else query.lower()
    if not needle:
        return

    for line_number, line in enumerate(text.splitlines(), start=1):
        line_haystack = line if case_sensitive else line.lower()
        if needle in line_haystack:
            matches.append({'path': os.path.relpath(path, root_real).replace('\\\\', '/'), 'lineNumber': line_number, 'line': line.strip()[:240]})
            if len(matches) >= max_results:
                return

if os.path.isfile(target_real):
    process_file(target_real)
else:
    for current_root, dirs, files in os.walk(target_real):
        dirs[:] = [d for d in dirs if d not in skip_dirs and not d.startswith('.')]
        for file_name in files:
            if len(matches) >= max_results:
                break
            if file_name.startswith('.'):
                continue
            process_file(os.path.join(current_root, file_name))
        if len(matches) >= max_results:
            break

print(json.dumps({'query': query, 'matches': matches, 'scannedFiles': scanned_files, 'truncated': len(matches) >= max_results}))
PY`;
}

function assertWorkspacePath(pathInput: string, policy: ReviewCommandPolicy): string {
  const trimmed = (pathInput || '.').trim();
  const normalized = trimmed.replace(/\\/g, '/');
  if (normalized.includes('\u0000')) {
    throw new ReviewPolicyError('Path contains null bytes');
  }
  if (normalized.startsWith('/') || normalized.startsWith('..') || normalized.includes('/../')) {
    throw new ReviewPolicyError('Path escapes workspace root');
  }
  const collapsed = normalized.split('/').filter((segment) => segment.length > 0 && segment !== '.').join('/');
  if (collapsed.startsWith('..')) {
    throw new ReviewPolicyError('Path escapes workspace root');
  }
  if (collapsed === '.git' || collapsed.startsWith('.git/')) {
    throw new ReviewPolicyError('Access to .git is denied by policy');
  }
  return `${policy.rootPath}/${collapsed}`;
}

/**
 * Executes one read-only review tool invocation inside the hydrated sandbox.
 * Mutating tools are intentionally downgraded to policy errors/results rather than executed.
 */
export async function executeReviewTool(
  sandbox: SandboxClient,
  action: Extract<ReviewAgentAction, { type: 'tool' }>,
  policy: ReviewCommandPolicy,
  maxFileBytes: number,
  authoritativeDiffSnapshot?: unknown
): Promise<ReviewToolContext> {
  if (action.tool === 'list_files') {
    const absolutePath = assertWorkspacePath(action.args.path ?? '.', policy);
    const output = await runSandboxCommand(sandbox, buildListFilesCommand(absolutePath, policy.rootPath));
    return { request: { path: action.args.path ?? '.' }, result: JSON.parse(output.stdout || '{}') };
  }

  if (action.tool === 'read_file') {
    const absolutePath = assertWorkspacePath(action.args.path, policy);
    const maxBytes = typeof action.args.maxBytes === 'number' && Number.isFinite(action.args.maxBytes)
      ? Math.max(1, Math.min(maxFileBytes, Math.floor(action.args.maxBytes)))
      : maxFileBytes;
    const output = await runSandboxCommand(sandbox, buildReadFileCommand(absolutePath, maxBytes, policy.rootPath));
    return { request: { path: action.args.path, maxBytes }, result: JSON.parse(output.stdout || '{}') };
  }

  if (action.tool === 'read_batch') {
    const maxBytes = typeof action.args.maxBytes === 'number' && Number.isFinite(action.args.maxBytes)
      ? Math.max(1, Math.min(maxFileBytes, Math.floor(action.args.maxBytes)))
      : maxFileBytes;
    const files: Array<Record<string, unknown>> = [];
    for (const requestedPath of action.args.paths) {
      const absolutePath = assertWorkspacePath(requestedPath, policy);
      const output = await runSandboxCommand(sandbox, buildReadFileCommand(absolutePath, maxBytes, policy.rootPath));
      const parsed = JSON.parse(output.stdout || '{}') as Record<string, unknown>;
      files.push({

      files.push({
        path: requestedPath,
        ...parsed,
      });
    }
    return { request: { paths: action.args.paths, maxBytes }, result: { files } };
  }

  if (action.tool === 'search_code') {
    const absolutePath = assertWorkspacePath(action.args.path ?? '.', policy);
    const query = action.args.query.trim();
    if (!query) {
      return {
        request: { query, path: action.args.path ?? '.', maxResults: action.args.maxResults, maxBytesPerFile: action.args.maxBytesPerFile },
        result: { error: 'search_code.query is required', matches: [], scannedFiles: 0, truncated: false },
      };
    }
    const maxResults =
      typeof action.args.maxResults === 'number' && Number.isFinite(action.args.maxResults)
        ? Math.max(1, Math.min(200, Math.floor(action.args.maxResults)))
        : 40;
    const maxBytesPerFile =
      typeof action.args.maxBytesPerFile === 'number' && Number.isFinite(action.args.maxBytesPerFile)
        ? Math.max(1_024, Math.min(maxFileBytes, Math.floor(action.args.maxBytesPerFile)))
        : Math.min(maxFileBytes, 24_000);
    const caseSensitive = action.args.caseSensitive === true;
    const output = await runSandboxCommand(
      sandbox,
      buildSearchCodeCommand({
        absolutePath,
        query,
        maxResults,
        maxBytesPerFile,
        rootPath: policy.rootPath,
        caseSensitive,
      })
    );
    return {
      request: { query, path: action.args.path ?? '.', maxResults, maxBytesPerFile, caseSensitive },
      result: JSON.parse(output.stdout || '{}'),
    };
  }

  if (action.tool === 'run_command') {
    return {
      request: { command: action.args.command, timeoutMs: action.args.timeoutMs ?? DEFAULT_COMMAND_TIMEOUT_MS },
      result: { error: 'run_command is disabled in review mode; use list_files, read_file, read_batch, search_code, or diff_summary only', disabled: true },
    };
  }

  if (action.tool === 'write_file') {
    return {
      request: { path: action.args.path },
      result: { ok: false, error: 'write_file is disabled in review mode; use read-only tools and return findings only', path: action.args.path },
    };
  }

  if (authoritativeDiffSnapshot !== undefined) {
    const maxBytes = typeof action.args.maxBytes === 'number' && Number.isFinite(action.args.maxBytes)
      ? Math.max(1_024, Math.min(policy.maxOutputBytes, Math.floor(action.args.maxBytes)))
      : Math.min(policy.maxOutputBytes, 64_000);
    return { request: { maxBytes }, result: clampAuthoritativeDiffSnapshot(authoritativeDiffSnapshot, maxBytes) };
  }

  return {
    request: { maxBytes: typeof action.args.maxBytes === 'number' ? action.args.maxBytes : undefined },
    result: { error: 'authoritative diff snapshot unavailable', changedFiles: [], patch: '', truncated: false },
  };
}

/**
 * Validates that a provider action conforms to the narrow review-tool contract before execution.
 */
export function validateReviewAgentAction(action: unknown): ReviewAgentAction {
  const record = asRecord(action);
  if (record.type === 'complete' || record.type === 'final') {
    if (record.finalOutput !== undefined && record.finalOutput !== null) {
      const summary = typeof record.summary === 'string' ? record.summary.trim() : undefined;
      return { type: 'complete', finalOutput: record.finalOutput, summary };
    }
    const summary = typeof record.summary === 'string' ? record.summary.trim() : '';
    if (!summary) {
      throw new ReviewPolicyError('Complete action requires finalOutput or a non-empty summary');
    }
    return { type: 'complete', summary };
  }
  if (record.type !== 'tool') {
    throw new ReviewPolicyError('Action type must be tool or complete');
  }
  const tool = typeof record.tool === 'string' ? record.tool : '';
  const args = asRecord(record.args);
  const optionalString = (value: unknown): string | undefined => (typeof value === 'string' ? value : undefined);
  const optionalNumber = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) ? value : undefined);
  const optionalBoolean = (value: unknown): boolean | undefined => (typeof value === 'boolean' ? value : undefined);
  switch (tool) {
    case 'list_files':
      if (args.path !== undefined && args.path !== null && typeof args.path !== 'string') throw new ReviewPolicyError('list_files.path must be a string when provided');
      return { type: 'tool', tool, args: { path: optionalString(args.path) } };
    case 'read_file':
      if (typeof args.path !== 'string' || !args.path.trim()) throw new ReviewPolicyError('read_file.path is required');
      if (args.maxBytes !== undefined && args.maxBytes !== null && (typeof args.maxBytes !== 'number' || !Number.isFinite(args.maxBytes))) throw new ReviewPolicyError('read_file.maxBytes must be a number when provided');
      return { type: 'tool', tool, args: { path: args.path, maxBytes: optionalNumber(args.maxBytes) } };
    case 'read_batch': {
      if (!Array.isArray(args.paths) || args.paths.length === 0 || args.paths.some((value) => typeof value !== 'string' || !value.trim())) {
        throw new ReviewPolicyError('read_batch.paths must be a non-empty string array');
      }
      if (args.maxBytes !== undefined && args.maxBytes !== null && (typeof args.maxBytes !== 'number' || !Number.isFinite(args.maxBytes))) throw new ReviewPolicyError('read_batch.maxBytes must be a number when provided');
      return { type: 'tool', tool, args: { paths: args.paths as string[], maxBytes: optionalNumber(args.maxBytes) } };
    }
    case 'search_code': {
      if (typeof args.query !== 'string' || !args.query.trim()) throw new ReviewPolicyError('search_code.query is required');
      if (args.path !== undefined && args.path !== null && (typeof args.path !== 'string' || !args.path.trim())) throw new ReviewPolicyError('search_code.path must be a non-empty string when provided');
      if (args.maxResults !== undefined && args.maxResults !== null && (typeof args.maxResults !== 'number' || !Number.isFinite(args.maxResults))) throw new ReviewPolicyError('search_code.maxResults must be a number when provided');
      if (args.maxBytesPerFile !== undefined && args.maxBytesPerFile !== null && (typeof args.maxBytesPerFile !== 'number' || !Number.isFinite(args.maxBytesPerFile))) throw new ReviewPolicyError('search_code.maxBytesPerFile must be a number when provided');
      if (args.caseSensitive !== undefined && args.caseSensitive !== null && typeof args.caseSensitive !== 'boolean') throw new ReviewPolicyError('search_code.caseSensitive must be a boolean when provided');
      return {
        type: 'tool',
        tool,
        args: {
          query: args.query,
          path: optionalString(args.path),
          maxResults: optionalNumber(args.maxResults),
          maxBytesPerFile: optionalNumber(args.maxBytesPerFile),
          caseSensitive: optionalBoolean(args.caseSensitive),
        },
      };
    }
    case 'write_file':
      if (typeof args.path !== 'string' || !args.path.trim()) throw new ReviewPolicyError('write_file.path is required');
      return { type: 'tool', tool, args: { path: args.path, content: typeof args.content === 'string' ? args.content : undefined } };
    case 'run_command':
      if (typeof args.command !== 'string' || !args.command.trim()) throw new ReviewPolicyError('run_command.command is required');
      if (args.timeoutMs !== undefined && (typeof args.timeoutMs !== 'number' || !Number.isFinite(args.timeoutMs))) throw new ReviewPolicyError('run_command.timeoutMs must be a number when provided');
      return { type: 'tool', tool, args: { command: args.command, timeoutMs: args.timeoutMs as number | undefined } };
    case 'diff_summary':
      if (args.maxBytes !== undefined && (typeof args.maxBytes !== 'number' || !Number.isFinite(args.maxBytes))) throw new ReviewPolicyError('diff_summary.maxBytes must be a number when provided');
      return { type: 'tool', tool, args: { maxBytes: args.maxBytes as number | undefined } };
    default:
      throw new ReviewPolicyError(`Tool '${tool}' is not supported in review mode`);
  }
}

/**
 * Captures the initial root listing and diff snapshot used to seed review analysis prompts.
 */
export async function snapshotInitialContext(sandbox: SandboxClient, maxFileBytes: number): Promise<{ rootListing: unknown; diffSnapshot: unknown }> {
  const policy: ReviewCommandPolicy = {
    commandAllow: [],
    commandDeny: [],
    maxCommandTimeoutMs: MAX_COMMAND_TIMEOUT_MS,
    maxOutputBytes: DEFAULT_REVIEW_MAX_OUTPUT_BYTES,
    rootPath: WORKSPACE_ROOT,
  };

  const rootListing = await executeReviewTool(sandbox, { type: 'tool', tool: 'list_files', args: { path: '.' } }, policy, maxFileBytes);
  const diffSnapshot = await executeReviewTool(sandbox, { type: 'tool', tool: 'diff_summary', args: { maxBytes: 32_000 } }, policy, maxFileBytes);
  return { rootListing, diffSnapshot };
}

import { approveReviewPolicy, deriveReviewPolicy } from '../../clients/worker/reviews.js';
import { getWorkerUrl } from '../../clients/worker/shared.js';
import { validateReviewCommitCheckpoint, validateReviewEntireIntentContext } from '../../commands/review/preflight.js';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { resolveReviewContext, type ResolveReviewContextProgressEvent } from './context.js';
import { buildStudioReviewRoutePath, resolveReviewGitProvenance } from './create-shared.js';
import { readStudioPreferences, updateStudioPolicyMode } from './session.js';

export type StudioReviewPolicyMode = 'auto' | 'review';

export interface StudioNewReviewPreflightResult {
  repo: string | null;
  branch: string | null;
  policyMode: StudioReviewPolicyMode;
  lastCheckpoints: 1 | 2 | 3;
  checkpointSelectionMode: 'latest' | 'last_n';
  checkpointId: string | null;
  commitSha: string | null;
  includedCheckpoints: Array<{
    checkpointId: string;
    commitSha: string;
    commitSubject: string;
  }>;
  ready: boolean;
  checks: Array<{
    code: 'checkpoint' | 'entire_context';
    label: string;
    ok: boolean;
    detail: string;
  }>;
  error?: {
    code: 'checkpoint_unavailable' | 'entire_context_unavailable' | 'unknown';
    message: string;
  };
}

function normalizeLastCheckpoints(value: number | null | undefined): 1 | 2 | 3 {
  if (value === 1 || value === 2 || value === 3) {
    return value;
  }
  return 2;
}

export interface StudioNewReviewStartResult {
  reviewId: string;
  routePath: string;
  policyMode: StudioReviewPolicyMode;
  status: 'policy_ready' | 'queued';
}

export interface StudioNewReviewStartStageEvent {
  type: 'stage';
  stage: ResolveReviewContextProgressEvent['stage'] | 'review_creation' | 'policy';
  state: 'active' | 'completed';
  label: string;
  detail: string;
}

export interface StudioNewReviewStartCompletedEvent extends StudioNewReviewStartResult {
  type: 'completed';
  detail: string;
}

export interface StudioNewReviewStartErrorEvent {
  type: 'error';
  message: string;
}

export type StudioNewReviewStartStreamEvent =
  | StudioNewReviewStartStageEvent
  | StudioNewReviewStartCompletedEvent
  | StudioNewReviewStartErrorEvent;

function shouldAbortStudioStart(signal: AbortSignal | undefined, abortBeforeReviewCreation: boolean): boolean {
  return abortBeforeReviewCreation && Boolean(signal?.aborted);
}

function preflightErrorCode(message: string): NonNullable<StudioNewReviewPreflightResult['error']>['code'] {
  const lower = message.toLowerCase();
  if (lower.includes('entire-checkpoint trailer') || lower.includes('no entire session history')) {
    return 'checkpoint_unavailable';
  }
  if (lower.includes('entire session') || lower.includes('checkpoint context')) {
    return 'entire_context_unavailable';
  }
  return 'unknown';
}

function normalizeStudioPolicyMode(value: string | null | undefined): StudioReviewPolicyMode {
  return value === 'review' ? 'review' : 'auto';
}

function resolveStudioRepoRoot(explicitRepoRoot?: string): string {
  if (explicitRepoRoot?.trim()) {
    return explicitRepoRoot.trim();
  }
  try {
    return new GitRepo(process.cwd()).getRepoRoot();
  } catch {
    return process.cwd();
  }
}

function normalizeExpectedContextField(value: string | null | undefined): string | null {
  const normalized = value?.trim();
  return normalized ? normalized : null;
}

export function studioBranchContextMatchesExpected(
  current: { repo: string; branch: string },
  expected?: { repo?: string | null; branch?: string | null }
): boolean {
  const expectedRepo = normalizeExpectedContextField(expected?.repo);
  const expectedBranch = normalizeExpectedContextField(expected?.branch);
  if (!expectedRepo || !expectedBranch) {
    return true;
  }
  return current.repo === expectedRepo && current.branch === expectedBranch;
}

export async function resolveStudioNewReviewPreflight(options?: {
  repoRoot?: string;
  lastCheckpoints?: number;
}): Promise<StudioNewReviewPreflightResult> {
  const repoRoot = resolveStudioRepoRoot(options?.repoRoot);
  const lastCheckpoints = normalizeLastCheckpoints(options?.lastCheckpoints ?? null);
  const preferences = await readStudioPreferences({ repoRoot });
  const policyMode = normalizeStudioPolicyMode(preferences.policyMode);
  let repo: string | null = null;
  let branch: string | null = null;
  try {
    const gitProvenance = resolveReviewGitProvenance(repoRoot);
    repo = gitProvenance.repo;
    branch = gitProvenance.branch;
  } catch {
    repo = null;
    branch = null;
  }

  let commitSha: string | null = null;
  let checkpointId: string | null = null;
  let includedCheckpoints: Array<{ checkpointId: string; commitSha: string; commitSubject: string }> = [];
  let checkpointSelectionMode: 'latest' | 'last_n' = lastCheckpoints > 1 ? 'last_n' : 'latest';
  let checkpointDetail = '';
  try {
    const checkpoint = validateReviewCommitCheckpoint('HEAD', repoRoot, {
      lastCheckpoints,
    });
    commitSha = checkpoint.commitSha;
    checkpointId = checkpoint.checkpointId;
    includedCheckpoints = checkpoint.includedCheckpoints ?? [];
    checkpointSelectionMode = checkpoint.checkpointSelectionMode === 'last_n' ? 'last_n' : 'latest';
    checkpointDetail =
      checkpointSelectionMode === 'last_n'
        ? `Resolved ${includedCheckpoints.length} checkpoints ending at ${checkpointId}.`
        : `Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}.`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId: null,
      commitSha: null,
      includedCheckpoints: [],
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: false,
          detail: message,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: 'Blocked until checkpoint target is available.',
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },
    };
  }

  try {
    const context = await validateReviewEntireIntentContext(
      {
        commitSha,
        checkpointId,
      },
      {
        summarizeSession: 'auto',
        allowBranchFallback: true,
      },
      repoRoot
    );
    const contextDetail =
      context.contextResolution === 'branch_fallback'
        ? `Using branch fallback checkpoint ${context.resolvedCheckpointId} from ${context.commitsAgo} commit(s) ago.`
        : 'Readable Entire checkpoint context found for current commit.';
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId,
      commitSha,
      includedCheckpoints,
      ready: true,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: checkpointDetail,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: true,
          detail: contextDetail,
        },
      ],
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      lastCheckpoints,
      checkpointSelectionMode,
      checkpointId,
      commitSha,
      includedCheckpoints,
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: checkpointDetail,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: message,
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },

      },
    };
  }
}

export async function startStudioNewReview(options: {
  policyMode: StudioReviewPolicyMode;
  lastCheckpoints?: number;
  repoRoot?: string;
  expectedRepo?: string | null;
  expectedBranch?: string | null;
  signal?: AbortSignal;
  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
}): Promise<StudioNewReviewStartResult> {
  let abortBeforeReviewCreation = true;
  const throwIfAborted = (): void => {
    if (!shouldAbortStudioStart(options.signal, abortBeforeReviewCreation)) {
      return;
    }
    const error = new Error('Studio review start aborted before completion.');
    error.name = 'AbortError';
    throw error;
  };
  const emitEvent = async (event: StudioNewReviewStartStreamEvent): Promise<void> => {
    throwIfAborted();
    try {
      await options.onEvent?.(event);
    } catch {
      // Start-flow events are best-effort only and must not abort review setup.
    }
  };

  throwIfAborted();
  const policyMode = normalizeStudioPolicyMode(options.policyMode);
  const lastCheckpoints = normalizeLastCheckpoints(options.lastCheckpoints ?? null);
  const repoRoot = resolveStudioRepoRoot(options.repoRoot);
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  const gitProvenance = resolveReviewGitProvenance(repoRoot);
  if (
    !studioBranchContextMatchesExpected(gitProvenance, {
      repo: options.expectedRepo,
      branch: options.expectedBranch,
    })
  ) {
    throw new Error(
      `Studio context changed to ${gitProvenance.branch} (${gitProvenance.repo}). Switch context in Home, then retry.`
    );
  }

  await updateStudioPolicyMode(policyMode, { repoRoot });
  const resolved = await resolveReviewContext({
    commitish: 'HEAD',
    projectRoot: '.',
    lastCheckpoints,
    signal: options.signal,
    onProgress: (event) => emitEvent({
      type: 'stage',
      stage: event.stage,
      state: event.state,
      label: event.label,
      detail: event.detail,
    }),
  });

  await emitEvent({
    type: 'stage',
    stage: 'review_creation',
    state: 'active',
    label: policyMode === 'review' ? 'Creating policy review' : 'Creating review',
    detail:
      policyMode === 'review'
        ? 'Creating the review and opening the policy screen.'
        : 'Creating the review record before queueing analysis.',
  });

  if (policyMode === 'review') {
    throwIfAborted();
    const derived = await deriveReviewPolicy(workerUrl, {
      workspaceId: resolved.workspaceId,
      deploymentId: resolved.deploymentId,
      policyMode: 'review',
      reviewBasis: 'checkpoint',
      provenance: resolved.resolvedProvenance,
    });
    // Once the review exists, finish the handoff even if the client disconnects.
    abortBeforeReviewCreation = false;

    await emitEvent({
      type: 'stage',
      stage: 'review_creation',
      state: 'completed',
      label: 'Policy review ready',
      detail: `Review ${derived.reviewId} is ready for policy confirmation.`,
    });

    const result: StudioNewReviewStartResult = {
      reviewId: derived.reviewId,
      routePath: buildStudioReviewRoutePath({
        reviewId: derived.reviewId,
        route: 'policy',
        repo: resolved.resolvedProvenance.repo,
        branch: resolved.resolvedProvenance.branch,
      }),
      policyMode,
      status: 'policy_ready',
    };
    await emitEvent({
      type: 'completed',
      ...result,
      detail: 'Policy review is ready. Opening the policy screen.',
    });
    return result;
  }

  throwIfAborted();
  const derived = await deriveReviewPolicy(workerUrl, {
    workspaceId: resolved.workspaceId,
    deploymentId: resolved.deploymentId,
    policyMode: 'auto',
    reviewBasis: 'checkpoint',
    provenance: resolved.resolvedProvenance,
  });
  // Once the review exists, finish the handoff even if the client disconnects.
  abortBeforeReviewCreation = false;
  await emitEvent({
    type: 'stage',
    stage: 'review_creation',
    state: 'completed',
    label: 'Review created',
    detail: `Review ${derived.reviewId} was created and is ready to queue.`,
  });
  await emitEvent({
    type: 'stage',
    stage: 'policy',
    state: 'active',
    label: 'Approving policy',
    detail: 'Applying the derived policy so Nimbus can start analysis.',
  });
  await approveReviewPolicy(workerUrl, derived.reviewId, {
    approvedPolicy: derived.derivedPolicy,
  });
  await emitEvent({
    type: 'stage',
    stage: 'policy',
    state: 'completed',
    label: 'Review queued',
    detail: `Review ${derived.reviewId} is queued and ready to stream live activity.`,
  });

  const result: StudioNewReviewStartResult = {
    reviewId: derived.reviewId,
    routePath: buildStudioReviewRoutePath({
      reviewId: derived.reviewId,
      route: 'reports',
      repo: resolved.resolvedProvenance.repo,
      branch: resolved.resolvedProvenance.branch,
    }),
    policyMode,
    status: 'queued',
  };
  await emitEvent({
    type: 'completed',
    ...result,
    detail: 'Review queued. Opening the live results route.',
  });
  return result;
}

export function shouldAbortStudioStartForTests(
  signal: AbortSignal | undefined,
  abortBeforeReviewCreation: boolean
): boolean {
  return shouldAbortStudioStart(signal, abortBeforeReviewCreation);
}

export async function emitStudioStartEventForTests(input: {
  signal?: AbortSignal;
  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
  event: StudioNewReviewStartStreamEvent;
}): Promise<void> {
  if (input.signal?.aborted) {
    const error = new Error('Studio review start aborted before completion.');
    error.name = 'AbortError';
    throw error;
  }
  try {
    await input.onEvent?.(input.event);
  } catch {
    // Best-effort only in tests as well.
  }
}

import { strict as assert } from 'assert';
