  setRecoveringReview(true);
  setRecoveryError(null);
  try {
    const response = await fetch(`${API_BASE}/api/reviews/${encodeURIComponent(reviewId)}/recover`, {
      method: 'POST',
    });
    const body = await response.json().catch(() => null);
    if (!response.ok) {
