   279	export async function manuallyFailReviewRun(
   280	  env: Env,
   281	  reviewId: string
   282	): Promise<{ action: 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
   283	  const review = await getReviewRun(env.DB, reviewId);
   284	  if (!review) {
   285	    return { action: 'failed', review: null };
   286	  }
   287	
   288	  if (review.status !== 'queued' && review.status !== 'running') {
   289	    throw new Error(`Review is ${review.status}; only queued or running reviews can be failed manually.`);
   290	  }
   291	
   292	  const message =
   293	    review.status === 'running'
   294	      ? 'Manual fail requested while review was stuck in running state.'
   295	      : 'Manual fail requested while review was queued.';
   296	
   297	  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
   298	    report: null,
   299	    markdownSummary: null,
   300	    errorCode: 'review_execution_aborted',
   301	    errorMessage: message,
   302	  });
   303	  await appendReviewEvent(env.DB, {
   304	    reviewId,
   305	    eventType: 'review_failed',
   306	    payload: {
   307	      code: 'review_execution_aborted',
   308	      message,
   309	      reason: 'manual_fail',
   310	      priorStatus: review.status,
   311	    },
   312	  });
   313	
   314	  return {
   315	    action: 'failed',
   316	    review: await getReviewRun(env.DB, reviewId),
   317	  };
   318	}

