function resolveStudioRepoRoot(explicitRepoRoot?: string): string {
  if (explicitRepoRoot?.trim()) {
    return explicitRepoRoot.trim();
  }
  try {
    return new GitRepo(process.cwd()).getRepoRoot();
  } catch {
    return process.cwd();
  }
