    headSha: null,
    policyMode: null,
    lastCheckpoints: null,
    refreshedAtMs: null,
    value: null,
  };
  inFlightByKey.clear();

  inFlightByKey.clear();
  resolveStudioNewReviewPreflightForCache = resolveStudioNewReviewPreflight;
}

