    cache.policyMode === policyMode &&
    cache.lastCheckpoints === lastCheckpoints
  ) {
    return cache.value;
  }
  return refreshPreflight(repoRoot, lastCheckpoints);
}

export function startStudioPreflightBackgroundPolling(options?: {
  repoRoot?: string;
}): void {
  if (headWatcher) {
    return;
