import { asRecord, clampText, extractJsonObject, stripCodeFences } from './helpers.js';
import {
  isMissingOpenRouterApiKeyError,
  isTimeoutLikeError,
  isWorkerToWorkerFetchRestriction,
  sanitizeErrorMessage,
  sleep,
} from './output.js';

const REVIEW_PROVIDER_TIMEOUT_MS = 120_000;
const REVIEW_PROVIDER_MAX_ATTEMPTS = 2;
const REVIEW_PROVIDER_RETRY_DELAY_MS = 750;
const OPENROUTER_CHAT_COMPLETIONS_URL = 'https://openrouter.ai/api/v1/chat/completions';
const REVIEW_HISTORY_MAX_BYTES = 120_000;

export type ReviewAgentHistoryEntry =
  | { role: 'assistant'; content: string }
  | { role: 'tool'; tool: string; output: unknown };

export interface ReviewAgentProvider {
  next(input: {
    prompt: string;
    model: string;
    reasoningEffort?: 'minimal' | 'low' | 'medium' | 'high';
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
    forceComplete?: boolean;
    abortSignal?: AbortSignal;
  }): Promise<ReviewAgentAction>;
}

function buildProviderAbortError(): Error {
  const error = new Error('Review analysis aborted by external signal');
  error.name = 'AbortError';
  return error;
}

const reviewAgentActionJsonSchema = {
  name: 'ReviewAgentAction',
  strict: true,
  schema: {
    type: 'object',
    additionalProperties: false,
    properties: {
      type: { type: 'string', enum: ['tool', 'complete', 'final'] },
      tool: {
        anyOf: [
          { type: 'string', enum: ['list_files', 'read_file', 'read_batch', 'diff_summary', 'search_code'] },
          { type: 'null' },
        ],
      },
      args: {
        anyOf: [
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              path: { anyOf: [{ type: 'string' }, { type: 'null' }] },
              paths: {
                anyOf: [
                  { type: 'array', items: { type: 'string' } },
                  { type: 'null' },
                ],
              },
              maxBytes: { anyOf: [{ type: 'number' }, { type: 'null' }] },
              query: { anyOf: [{ type: 'string' }, { type: 'null' }] },
              maxResults: { anyOf: [{ type: 'number' }, { type: 'null' }] },
              maxBytesPerFile: { anyOf: [{ type: 'number' }, { type: 'null' }] },
              caseSensitive: { anyOf: [{ type: 'boolean' }, { type: 'null' }] },
            },
            required: ['path', 'paths', 'maxBytes', 'query', 'maxResults', 'maxBytesPerFile', 'caseSensitive'],
          },
          { type: 'null' },
        ],
      },
      summary: { anyOf: [{ type: 'string' }, { type: 'null' }] },
      finalOutput: {
        anyOf: [
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              findings: {
                type: 'array',
                items: {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    severity: { type: 'string', enum: ['info', 'low', 'medium', 'high', 'critical'] },
                    category: { type: 'string', enum: ['security', 'logic', 'style', 'breaking-change'] },
                    passType: { type: 'string', enum: ['single'] },
                    locations: {
                      type: 'array',
                      items: {
                        type: 'object',
                        additionalProperties: false,
                        properties: {
                          filePath: { type: 'string' },
                          startLine: { anyOf: [{ type: 'number' }, { type: 'null' }] },
                          endLine: { anyOf: [{ type: 'number' }, { type: 'null' }] },
                        },
                        required: ['filePath', 'startLine', 'endLine'],
                      },
                    },
                    description: { type: 'string' },
                    suggestedFix: { type: 'string' },
                    failingScenario: { type: 'string' },
                    evidence: { type: 'string' },
                    guardGap: { type: 'string' },
                  },
                  required: ['severity', 'category', 'passType', 'locations', 'description', 'suggestedFix', 'failingScenario', 'evidence', 'guardGap'],
                },
              },
              summary: { type: 'string' },
              furtherPassesLowYield: { type: 'boolean' },
            },
            required: ['findings', 'summary', 'furtherPassesLowYield'],
          },
          { type: 'null' },
        ],
      },
    },
    required: ['type', 'tool', 'args', 'summary', 'finalOutput'],
  },
} as const;

function parseOpenRouterContent(payload: unknown): string {
  const record = asRecord(payload);
  const choices = Array.isArray(record.choices) ? record.choices : [];
  const first = asRecord(choices[0]);
  const message = asRecord(first.message);
  const content = message.content;

  if (typeof content === 'string') {
    return content.trim();
  }

  if (Array.isArray(content)) {
    return content
      .map((part) => {
        const entry = asRecord(part);
        return typeof entry.text === 'string' ? entry.text : '';
      })
      .join('')
      .trim();
  }

  return '';
}

function buildHistoryForPrompt(history: ReviewAgentHistoryEntry[]): string {
  const serialized = JSON.stringify(history);
  return clampText(serialized, REVIEW_HISTORY_MAX_BYTES).text;
}

function buildOpenRouterStepPrompt(input: {
  prompt: string;
  maxSteps: number;
  step: number;
  history: ReviewAgentHistoryEntry[];
  forceComplete: boolean;
}): string {
  return [
    input.prompt,
    '',
    'Agent loop instructions:',
    `- Current step: ${input.step} of ${input.maxSteps}.`,
    '- You are inside Nimbus\'s internal review harness loop.',
    '- Decide whether to request ONE read-only tool call or finish with complete structured review JSON.',
    '- Tools available: list_files, read_file, read_batch, diff_summary, search_code.',
    '- Never request write_file or run_command.',
    input.forceComplete
      ? '- HARD REQUIREMENT: return type="complete" now. Do not request any tool.'
      : '- If critical evidence is still missing, request one targeted tool call; otherwise finish.',
    '- For type="complete", set finalOutput to a JSON object payload for ReviewAnalysisOutputV2.',
    '- For type="complete", set summary to null or a short plain-text note (never structured payload).',
    '- Return ONLY a valid action object matching the response schema.',
    '',
    `Prior loop history JSON: ${buildHistoryForPrompt(input.history)}`,
  ].join('\n');
}

export class OpenRouterReviewProvider implements ReviewAgentProvider {
  constructor(
    private readonly apiKey: string,
    private readonly validateAction: (action: unknown) => ReviewAgentAction,
    private readonly httpReferer: string,
    private readonly xTitle: string
  ) {}

  async next(input: {
    prompt: string;
    model: string;
    reasoningEffort?: 'minimal' | 'low' | 'medium' | 'high';
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
    forceComplete?: boolean;
    abortSignal?: AbortSignal;
  }): Promise<ReviewAgentAction> {
    const forceComplete = input.forceComplete === true;

    for (let attempt = 1; attempt <= REVIEW_PROVIDER_MAX_ATTEMPTS; attempt += 1) {
      const controller = new AbortController();
      let timeoutId: ReturnType<typeof setTimeout> | null = null;
      const handleExternalAbort = (): void => {
        controller.abort();
      };

      try {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        input.abortSignal?.addEventListener('abort', handleExternalAbort, { once: true });
        const requestPromise = fetch(OPENROUTER_CHAT_COMPLETIONS_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${this.apiKey}`,
            'HTTP-Referer': this.httpReferer,
            'X-Title': this.xTitle,
          },
          body: JSON.stringify({
            model: input.model,
            ...(input.reasoningEffort ? { reasoning: { effort: input.reasoningEffort } } : {}),
            response_format: { type: 'json_schema', json_schema: reviewAgentActionJsonSchema },
            plugins: [{ id: 'response-healing' }],
            messages: [
              {
                role: 'user',
                content: buildOpenRouterStepPrompt({
                  prompt: input.prompt,
                  maxSteps: input.maxSteps,
                  step: input.step,
                  history: input.history,
                  forceComplete,
                }),
              },
            ],
          }),
          signal: controller.signal,
        });

        const timeoutPromise = new Promise<never>((_, reject) => {
          timeoutId = setTimeout(() => {
            controller.abort('review_provider_timeout');
            reject(new Error(`Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds`));
          }, REVIEW_PROVIDER_TIMEOUT_MS);
        });

        const response = await Promise.race([requestPromise, timeoutPromise]);
        const bodyText = await response.text();
        if (!response.ok) {
          const providerErrorBody = sanitizeErrorMessage(bodyText, { openrouterApiKey: this.apiKey });
          if (isMissingOpenRouterApiKeyError(providerErrorBody) || response.status === 401 || response.status === 403) {
            throw new Error('missing_openrouter_api_key: valid OpenRouter API key is required for review analysis');
          }
          if (isWorkerToWorkerFetchRestriction(response.status, providerErrorBody)) {

          if (isWorkerToWorkerFetchRestriction(response.status, providerErrorBody)) {
            throw new Error(
              `Review analysis provider request blocked by Cloudflare Worker-to-Worker fetch restriction (error code 1042). Enable the 'global_fetch_strictly_public' compatibility flag on this worker or switch to a service binding.${providerErrorBody ? ` Provider response: ${providerErrorBody}` : ''}`
            );
          }

          const transientStatus = response.status >= 500 || response.status === 429;
          const statusError = new Error(
            transientStatus
              ? `Review analysis provider temporarily unavailable (status ${response.status})${providerErrorBody ? `: ${providerErrorBody}` : ''}`
              : `Review analysis provider request failed with status ${response.status}${providerErrorBody ? `: ${providerErrorBody}` : ''}`
          );

          if (transientStatus && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
            await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
            continue;
          }

          throw statusError;
        }

        let parsedResponse: unknown = null;
        try {
          parsedResponse = bodyText ? JSON.parse(bodyText) : null;
        } catch {
          parsedResponse = null;
        }

        const content = parseOpenRouterContent(parsedResponse);
        if (!content) {
          throw new Error('Review analysis provider returned empty model content');
        }
        const actionPayload = JSON.parse(extractJsonObject(stripCodeFences(content))) as unknown;
        const action = this.validateAction(actionPayload);
        if (forceComplete && action.type !== 'complete') {
          throw new Error('Review analysis finalization step must return type="complete"');
        }
        return action;
      } catch (error) {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        const timeoutLike = isTimeoutLikeError(error);
        const transientNetworkError = error instanceof Error && /fetch failed|network|connection reset|econnreset|socket hang up/i.test(error.message);
        if ((timeoutLike || transientNetworkError) && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
          await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
          continue;
        }
        if (timeoutLike) {
          throw new Error(
            `Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds (attempt ${attempt}/${REVIEW_PROVIDER_MAX_ATTEMPTS})`
          );
        }
        throw error;
      } finally {
        input.abortSignal?.removeEventListener('abort', handleExternalAbort);
        if (timeoutId !== null) {
          clearTimeout(timeoutId);
        }
      }
    }

    throw new Error('Review analysis provider exhausted retry attempts without a valid response');
  }
}

export class CloudflareAgentSdkReviewProvider implements ReviewAgentProvider {
  constructor(
    private readonly endpoint: string,
    private readonly authToken: string | null,
    private readonly serviceBinding: Fetcher | null,
    private readonly openrouterApiKey: string | null,
    private readonly validateAction: (action: unknown) => ReviewAgentAction
  ) {}

  async next(input: {
    prompt: string;
    model: string;
    reasoningEffort?: 'minimal' | 'low' | 'medium' | 'high';
    maxSteps: number;
    step: number;
    history: ReviewAgentHistoryEntry[];
    forceComplete?: boolean;
    abortSignal?: AbortSignal;
  }): Promise<ReviewAgentAction> {
    const requestFetch = this.serviceBinding ? this.serviceBinding.fetch.bind(this.serviceBinding) : fetch;

    for (let attempt = 1; attempt <= REVIEW_PROVIDER_MAX_ATTEMPTS; attempt += 1) {
      const controller = new AbortController();
      let timeoutId: ReturnType<typeof setTimeout> | null = null;
      const handleExternalAbort = (): void => {
        controller.abort();
      };

      try {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        input.abortSignal?.addEventListener('abort', handleExternalAbort, { once: true });
        const requestPromise = requestFetch(this.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(this.authToken ? { Authorization: `Bearer ${this.authToken}` } : {}),
            ...(this.openrouterApiKey ? { 'X-Openrouter-Api-Key': this.openrouterApiKey } : {}),
          },
          body: JSON.stringify({
            mode: 'workspace_task',
            prompt: input.prompt,
            model: input.model,
            ...(input.reasoningEffort ? { reasoningEffort: input.reasoningEffort } : {}),
            maxSteps: input.maxSteps,
            step: input.step,
            history: input.history,
            ...(input.forceComplete === true ? { forceComplete: true } : {}),
          }),
          signal: controller.signal,
        });

        const timeoutPromise = new Promise<never>((_, reject) => {
          timeoutId = setTimeout(() => {
            controller.abort('review_provider_timeout');
            reject(new Error(`Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds`));
          }, REVIEW_PROVIDER_TIMEOUT_MS);
        });

        const response = await Promise.race([requestPromise, timeoutPromise]);
        if (!response.ok) {
          const providerErrorBody = sanitizeErrorMessage(await response.text(), { openrouterApiKey: this.openrouterApiKey });
          if (isMissingOpenRouterApiKeyError(providerErrorBody)) {
            throw new Error(
              'Review analysis provider is missing an OpenRouter API key. Configure OPENROUTER_API_KEY for nimbus-agent-endpoint or pass X-Openrouter-Api-Key from the caller.'
            );
          }
          if (isWorkerToWorkerFetchRestriction(response.status, providerErrorBody)) {
            throw new Error(
              `Review analysis provider request blocked by Cloudflare Worker-to-Worker fetch restriction (error code 1042). Enable the 'global_fetch_strictly_public' compatibility flag on this worker or switch to a service binding.${providerErrorBody ? ` Provider response: ${providerErrorBody}` : ''}`
            );
          }

          const transientStatus = response.status >= 500 || response.status === 429;
          const statusError = new Error(
            transientStatus
              ? `Review analysis provider temporarily unavailable (status ${response.status})${providerErrorBody ? `: ${providerErrorBody}` : ''}`
              : `Review analysis provider request failed with status ${response.status}${providerErrorBody ? `: ${providerErrorBody}` : ''}`
          );

          if (transientStatus && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
            await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
            continue;
          }

          throw statusError;
        }

        const parsed = (await response.json()) as unknown;
        const action = asRecord(parsed).action;
        const validatedAction = this.validateAction(action);
        if (input.forceComplete === true && validatedAction.type !== 'complete') {
          throw new Error('Review analysis finalization step must return type="complete"');
        }

        }
        return validatedAction;
      } catch (error) {
        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        const timeoutLike = isTimeoutLikeError(error);
        const transientNetworkError = error instanceof Error && /fetch failed|network|connection reset|econnreset|socket hang up/i.test(error.message);
        if ((timeoutLike || transientNetworkError) && attempt < REVIEW_PROVIDER_MAX_ATTEMPTS) {
          await sleep(REVIEW_PROVIDER_RETRY_DELAY_MS * attempt);
          continue;
        }
        if (timeoutLike) {
          throw new Error(
            `Review analysis provider request timed out after ${Math.floor(REVIEW_PROVIDER_TIMEOUT_MS / 1000)} seconds (attempt ${attempt}/${REVIEW_PROVIDER_MAX_ATTEMPTS})`
          );
        }
        throw error;
      } finally {
        input.abortSignal?.removeEventListener('abort', handleExternalAbort);
        if (timeoutId !== null) {
          clearTimeout(timeoutId);
        }
      }
    }

    throw new Error('Review analysis provider exhausted retry attempts without a valid response');
  }
}

import type { AuthContext, Env, ReviewRunStatus } from '../../types.js';
import {
  getReviewRunAccountId,
  getWorkspaceAccountId,
} from '../../lib/db.js';
import { canAccessAccount } from '../../lib/authz.js';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Idempotency-Key, X-Review-Github-Token, X-Openrouter-Api-Key, X-Nimbus-Api-Key',
};

export const REVIEW_STREAM_POLL_INTERVAL_MS = 1000;
export const REVIEW_STREAM_HEARTBEAT_INTERVAL_MS = 1000;
export const REVIEW_TERMINAL_EVENT_GRACE_MS = 1000;
export const REVIEW_STREAM_STATUS_REFRESH_POLLS = 5;

function parseNonNegativeInteger(value: string | null): number | null {
  const parsed = Number.parseInt(value ?? '', 10);
  if (!Number.isFinite(parsed) || parsed < 0) {
    return null;
  }
  return parsed;
}

function readTrimmedHeader(request: Request, headerName: string): string | null {
  const value = request.headers.get(headerName);
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', ...corsHeaders },
  });
}

export async function requireWorkspaceAccess(env: Env, workspaceId: string, authContext: AuthContext): Promise<Response | null> {
  const accountId = await getWorkspaceAccountId(env.DB, workspaceId);
  if (!canAccessAccount(authContext, accountId)) {
    return jsonResponse({ error: 'Workspace not found' }, 404);
  }
  return null;
}

export async function requireReviewAccess(env: Env, reviewId: string, authContext: AuthContext): Promise<Response | null> {
  const accountId = await getReviewRunAccountId(env.DB, reviewId);
  if (!canAccessAccount(authContext, accountId)) {
    return jsonResponse({ error: 'Review not found' }, 404);
  }
  return null;
}

export function formatSseData(payload: unknown): string {
  return `data: ${JSON.stringify(payload)}\n\n`;
}

export function formatSseDataWithId(seq: number, payload: unknown): string {
  return `id: ${seq}\ndata: ${JSON.stringify(payload)}\n\n`;
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function resolveFromSequence(request: Request): number {
  const url = new URL(request.url);
  const fromParam = parseNonNegativeInteger(url.searchParams.get('from'));
  const lastEventId = parseNonNegativeInteger(request.headers.get('Last-Event-ID'));

  if (typeof lastEventId === 'number') {
    return lastEventId;
  }
  if (typeof fromParam === 'number') {
    return fromParam;
  }
  return 0;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

export function isSeverityThreshold(value: unknown): value is 'low' | 'medium' | 'high' | 'critical' {
  return value === 'low' || value === 'medium' || value === 'high' || value === 'critical';
}

export function readReviewGithubTokenHeader(request: Request): string | null {
  return readTrimmedHeader(request, 'X-Review-Github-Token');
}

export function readOpenrouterApiKeyHeader(request: Request): string | null {
  return readTrimmedHeader(request, 'X-Openrouter-Api-Key');
}

export function isReviewStatusActive(status: ReviewRunStatus): boolean {
  return (
    status === 'policy_pending' ||
    status === 'policy_ready' ||
    status === 'policy_approved' ||
    status === 'queued' ||
    status === 'running'
  );
}

import { execFileSync } from 'child_process';
import { readFileSync, watch, type FSWatcher } from 'fs';
import { join } from 'path';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { resolveStudioNewReviewPreflight, type StudioNewReviewPreflightResult } from './studio-create.js';

interface PreflightCacheState {
  headSha: string | null;
  policyMode: 'auto' | 'review' | null;
  lastCheckpoints: 1 | 2 | 3 | null;
  refreshedAtMs: number | null;
  value: StudioNewReviewPreflightResult | null;
}

const PREFLIGHT_CACHE_MAX_AGE_MS = 8_000;

let cache: PreflightCacheState = {
  headSha: null,
  policyMode: null,
  lastCheckpoints: null,
  refreshedAtMs: null,
  value: null,
};
const inFlightByKey = new Map<string, Promise<StudioNewReviewPreflightResult>>();
let headWatcher: FSWatcher | null = null;
let refWatcher: FSWatcher | null = null;
let studioPreferencesWatcher: FSWatcher | null = null;
let refreshDebounceTimer: NodeJS.Timeout | null = null;
let resolveStudioNewReviewPreflightForCache: typeof resolveStudioNewReviewPreflight = resolveStudioNewReviewPreflight;

function resolveHeadSha(repoRoot: string): string | null {
  try {
    return new GitRepo(repoRoot).resolveCommitSha('HEAD');
  } catch {
    return null;
  }
}

function resolveStudioPolicyMode(repoRoot: string): 'auto' | 'review' | null {
  try {
    const raw = JSON.parse(readFileSync(join(repoRoot, '.nimbus', 'studio.json'), 'utf8')) as {
      policyMode?: unknown;
    };
    if (raw.policyMode === 'auto' || raw.policyMode === 'review') {
      return raw.policyMode;
    }
    return null;
  } catch {
    return null;
  }
}

async function refreshPreflight(repoRoot: string, lastCheckpoints: 1 | 2 | 3): Promise<StudioNewReviewPreflightResult> {
  const inFlightKey = `${repoRoot}:${lastCheckpoints}`;
  const existing = inFlightByKey.get(inFlightKey);
  if (existing) {
    return existing;
  }
  const pending = (async () => {
    const result = await resolveStudioNewReviewPreflightForCache({ repoRoot, lastCheckpoints });
    cache = {
      headSha: resolveHeadSha(repoRoot),
      policyMode: resolveStudioPolicyMode(repoRoot),
      lastCheckpoints,
      refreshedAtMs: Date.now(),
      value: result,
    };
    return result;
  })();
  inFlightByKey.set(inFlightKey, pending);
  try {
    return await pending;
  } finally {
    if (inFlightByKey.get(inFlightKey) === pending) {
      inFlightByKey.delete(inFlightKey);
    }
  }
}

function resolveGitDir(repoRoot: string): string | null {
  try {
    const output = execFileSync('git', ['rev-parse', '--git-dir'], {
      cwd: repoRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .toString()
      .trim();
    if (!output) {
      return null;
    }
    return output.startsWith('/') ? output : join(repoRoot, output);
  } catch {
    return null;
  }
}

function resolveHeadRef(gitDir: string): string | null {
  try {
    const output = readFileSync(join(gitDir, 'HEAD'), 'utf8').trim();
    if (!output.startsWith('ref:')) {
      return null;
    }
    const headRef = output.slice(4).trim();
    return headRef || null;
  } catch {
    return null;
  }
}

function queueRefresh(repoRoot: string): void {
  if (refreshDebounceTimer) {
    clearTimeout(refreshDebounceTimer);
  }
  refreshDebounceTimer = setTimeout(() => {
    refreshDebounceTimer = null;
    void refreshPreflight(repoRoot, 2).catch(() => undefined);
  }, 250);
  if (typeof refreshDebounceTimer.unref === 'function') {
    refreshDebounceTimer.unref();
  }
}

function closeWatchers(): void {
  if (headWatcher) {
    headWatcher.close();
    headWatcher = null;
  }
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  if (studioPreferencesWatcher) {
    studioPreferencesWatcher.close();
    studioPreferencesWatcher = null;
  }
}

function watchHeadRefPath(repoRoot: string, gitDir: string): void {
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  const headRef = resolveHeadRef(gitDir);
  if (!headRef || !headRef.startsWith('refs/')) {
    return;
  }
  const headRefPath = join(gitDir, ...headRef.split('/'));
  try {
    refWatcher = watch(headRefPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    refWatcher = null;
  }
}

export async function getStudioNewReviewPreflightCached(options?: {
  repoRoot?: string;
  lastCheckpoints?: 1 | 2 | 3;
}): Promise<StudioNewReviewPreflightResult> {
  const repoRoot = options?.repoRoot ?? process.cwd();
  const lastCheckpoints = options?.lastCheckpoints ?? 2;
  const headSha = resolveHeadSha(repoRoot);
  const policyMode = resolveStudioPolicyMode(repoRoot);
  const cacheIsFresh =
    typeof cache.refreshedAtMs === 'number' && Date.now() - cache.refreshedAtMs <= PREFLIGHT_CACHE_MAX_AGE_MS;
  if (
    cache.value &&
    cacheIsFresh &&
    cache.headSha &&
    headSha &&
    cache.headSha === headSha &&
    cache.policyMode === policyMode &&
    cache.lastCheckpoints === lastCheckpoints
  ) {
    return cache.value;
  }
  return refreshPreflight(repoRoot, lastCheckpoints);
}

export function startStudioPreflightBackgroundPolling(options?: {
  repoRoot?: string;
}): void {
  if (headWatcher) {
    return;
  }
  const repoRoot = options?.repoRoot ?? process.cwd();
  const gitDir = resolveGitDir(repoRoot);

  void refreshPreflight(repoRoot, 2).catch(() => undefined);
  if (!gitDir) {
    return;
  }

  const headPath = join(gitDir, 'HEAD');
  try {
    headWatcher = watch(headPath, () => {
      watchHeadRefPath(repoRoot, gitDir);
      queueRefresh(repoRoot);
    });
  } catch {
    headWatcher = null;
    return;
  }
  watchHeadRefPath(repoRoot, gitDir);
  const studioPreferencesPath = join(repoRoot, '.nimbus', 'studio.json');
  try {
    studioPreferencesWatcher = watch(studioPreferencesPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    studioPreferencesWatcher = null;
  }
}

export function stopStudioPreflightBackgroundPolling(): void {
  closeWatchers();
  if (refreshDebounceTimer) {
    clearTimeout(refreshDebounceTimer);
    refreshDebounceTimer = null;
  }
}

export function setStudioPreflightResolverForTests(
  resolver: typeof resolveStudioNewReviewPreflight | null
): void {
  resolveStudioNewReviewPreflightForCache = resolver ?? resolveStudioNewReviewPreflight;
}

export function resetStudioPreflightCacheForTests(): void {
  stopStudioPreflightBackgroundPolling();
  cache = {
    headSha: null,
    policyMode: null,
    lastCheckpoints: null,
    refreshedAtMs: null,
    value: null,
  };
  inFlightByKey.clear();
  resolveStudioNewReviewPreflightForCache = resolveStudioNewReviewPreflight;
}

