const REVIEW_STALE_RUNNING_GRACE_MS = 60_000;
export const REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS = 120_000;

function parseTimeoutMs(value: string | undefined, fallback: number): number {
  if (typeof value !== 'string') {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }
  return parsed;
}

function parseMaxRetryCount(value: string | undefined, fallbackAttempts: number): number {
  const parsedAttempts = Number.parseInt(value ?? '', 10);
  const attempts = Number.isFinite(parsedAttempts) && parsedAttempts > 0 ? parsedAttempts : fallbackAttempts;
  return Math.max(0, attempts - 1);
}

function hasLocalCochangeProvenance(payload: unknown): boolean {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return false;
  }
  const record = payload as Record<string, unknown>;
  const provenance = record.provenance;
  if (!provenance || typeof provenance !== 'object' || Array.isArray(provenance)) {
    return false;
  }
  const localCochange = (provenance as Record<string, unknown>).localCochange;
  if (!localCochange || typeof localCochange !== 'object' || Array.isArray(localCochange)) {
    return false;
  }
  const candidate = localCochange as Record<string, unknown>;
  if (candidate.source !== 'local_git') {
    return false;
  }
  if (!Object.prototype.hasOwnProperty.call(candidate, 'relatedByChangedPath')) {
    return false;
  }
  const relatedByChangedPath = candidate.relatedByChangedPath;
  return Boolean(relatedByChangedPath !== null && typeof relatedByChangedPath === 'object' && !Array.isArray(relatedByChangedPath));
}

function isValidScopedGithubToken(value: string): boolean {
  const token = value.trim();
  if (!token) {
    return false;
  }
  return /^(ghp_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})$/.test(token);
}

export async function recoverStaleRunningReviewIfNeeded(
  env: Env,
  reviewId: string,
  review: { status: ReviewRunStatus; startedAt: string | null; updatedAt: string; createdAt: string; attemptCount: number },
  cochangeGithubToken?: string | null,
  openrouterApiKey?: string | null,
  options?: { markFailedWhenRetryUnavailable?: boolean; noAuthTerminalGraceMs?: number }
): Promise<void> {
  if (review.status !== 'running') {
    return;
  }
  const attemptTimeoutMs = parseTimeoutMs(env.ATTEMPT_TIMEOUT_MS, 600_000);
  const staleThresholdMs = attemptTimeoutMs + REVIEW_STALE_RUNNING_GRACE_MS;
  const startedMs = Date.parse(review.startedAt ?? review.updatedAt ?? review.createdAt);
  if (!Number.isFinite(startedMs)) {
    return;
  }
  const staleForMs = Date.now() - startedMs;
  if (staleForMs < staleThresholdMs) {
    return;
  }

  const maxRetries = parseMaxRetryCount(env.MAX_ATTEMPTS, 3);
  const requestPayload = await getReviewRunRequestPayload(env.DB, reviewId);
  const canRetryWithoutGithubToken = hasLocalCochangeProvenance(requestPayload);
  const rawScopedToken = typeof cochangeGithubToken === 'string' && cochangeGithubToken.trim() ? cochangeGithubToken.trim() : null;
  const scopedGithubToken = rawScopedToken && isValidScopedGithubToken(rawScopedToken) ? rawScopedToken : null;
  const hasInvalidScopedToken = Boolean(rawScopedToken) && !scopedGithubToken;
  if (review.attemptCount <= maxRetries && env.REVIEWS_QUEUE && (scopedGithubToken || canRetryWithoutGithubToken)) {
    await updateReviewRunStatus(env.DB, reviewId, 'queued', {
      report: null,
      markdownSummary: null,
      startedAt: null,
      finishedAt: null,
      errorCode: 'retry_scheduled',
      errorMessage: `Review execution stalled in running state for ${Math.floor(staleForMs / 1000)}s.`,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_retry_scheduled',
      payload: {
        attemptCount: review.attemptCount,
        maxRetries,
        reason: 'stale_running_timeout',
        staleForSeconds: Math.floor(staleForMs / 1000),
        authMode: scopedGithubToken ? 'scoped_request_token' : 'local_cochange_only',
      },
    });
    await env.REVIEWS_QUEUE.send(createReviewQueueMessage(reviewId, scopedGithubToken, openrouterApiKey));
    return;
  }

  if (options?.markFailedWhenRetryUnavailable === false) {
    const noAuthTerminalGraceMs =
      typeof options.noAuthTerminalGraceMs === 'number' && options.noAuthTerminalGraceMs >= 0
        ? options.noAuthTerminalGraceMs
        : REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS;
    if (staleForMs < staleThresholdMs + noAuthTerminalGraceMs) {
      return;
    }
  }

  const missingTokenSuffix =
    !scopedGithubToken && !canRetryWithoutGithubToken
      ? ' No retry was schedul…7006 chars truncated…value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function readOptionalString(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function canFinalizeSuccessfulReview(review: ReviewRunResponse | null): boolean {
  if (!review) {
    return false;
  }
  if (review.status === 'running') {
    return true;
  }
  return review.status === 'queued' && review.error?.code === 'retry_scheduled';
}

async function persistSuccessfulReviewStatusIfCurrent(input: {
  db: D1Database;
  reviewId: string;
  report: ReviewReport;
  expectedAttemptCount?: number;
}): Promise<boolean> {
  const now = new Date().toISOString();
  const sql = [
    'UPDATE review_runs SET status = ?, updated_at = ?, report_json = ?, markdown_summary = ?, error_code = NULL, error_message = NULL, finished_at = COALESCE(finished_at, ?)',
    "WHERE id = ? AND (status = 'running' OR (status = 'queued' AND error_code = 'retry_scheduled'))",
  ];
  const values: Array<string | number | null> = [
    'succeeded',
    now,
    JSON.stringify(stripSensitiveTokenFields(input.report)),
    typeof input.report.markdownSummary === 'string'
      ? (stripSensitiveTokenFields(input.report.markdownSummary) as string)
      : input.report.markdownSummary,
    now,
    input.reviewId,
  ];

  if (typeof input.expectedAttemptCount === 'number') {
    sql.push(' AND attempt_count = ?');
    values.push(input.expectedAttemptCount);
  }

  const result = await input.db.prepare(sql.join(' ')).bind(...values).run();
  return (result.meta?.changes ?? 0) > 0;
}

/**
 * Persists successful review output, assigns branch-stable finding numbers, and emits completion events.
 */
export async function finalizeSuccessfulReview(
  env: Env,
  reviewId: string,
  payload: Record<string, unknown>,
  report: ReviewReport,
  options?: {
    expectedAttemptCount?: number;
  }
): Promise<void> {
  const latest = await getReviewRun(env.DB, reviewId);
  if (!latest || !canFinalizeSuccessfulReview(latest)) {
    return;
  }
  if (typeof options?.expectedAttemptCount === 'number' && latest.attemptCount !== options.expectedAttemptCount) {
    return;
  }

  const payloadRecord = asRecord(payload);
  const requestProvenance = asRecord(payloadRecord.provenance);
  const reviewRepo = readOptionalString(requestProvenance.repo);
  const reviewBranch = readOptionalString(requestProvenance.branch);
  if (!reviewRepo || !reviewBranch) {
    throw new Error('Review request payload missing required provenance.repo or provenance.branch.');
  }

  const findingSequenceStart = (await getHighestFindingNumberForBranch(env.DB, reviewRepo, reviewBranch)) + 1;
  const findingsWithSequence = report.findings.map((finding, index) => ({
    ...finding,
    sequence: findingSequenceStart + index,
  }));
  const reportWithSequence: ReviewReport = {
    ...report,
    findings: findingsWithSequence,
  };

  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_finalize_started',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await replaceReviewFindings(env.DB, reviewId, findingsWithSequence, { startNumber: findingSequenceStart });
  const persisted = await persistSuccessfulReviewStatusIfCurrent({
    db: env.DB,
    reviewId,
    report: reportWithSequence,
    expectedAttemptCount: options?.expectedAttemptCount,
  });
  if (!persisted) {
    return;
  }
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_findings_persisted',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_succeeded',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_succeeded',
    payload: {
      recommendation: report.summary.recommendation,
      findingCount: report.findings.length,
    },
  });
}

/**
 * Persists a terminal failed state and emits failure events, including context-assembly failures when applicable.
 */
export async function finalizeFailedReview(
  env: Env,
  reviewId: string,
  input: {
    errorCode: string;
    message: string;
    contextAssemblyErrorCode?: string | null;
  }
): Promise<void> {
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    errorCode: input.errorCode,
    errorMessage: input.message,
  });
  try {
    if (input.contextAssemblyErrorCode) {
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_context_assembly_failed',
        payload: {
          code: input.contextAssemblyErrorCode,
          message: input.message,
        },
      });
    }
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: input.errorCode,
        message: input.message,
      },
    });
  } catch {
    // Best-effort terminal event.
  }
}

