        },
        {
          summarizeSession: 'auto',
          allowBranchFallback: true,
        },
        process.cwd()
      );
    }

    spinner.stop(
      entireContextResolution.contextResolution === 'branch_fallback'
        ? `Entire session metadata resolved via branch fallback (${entireContextResolution.resolvedCheckpointId})`
