  };
}

function normalizeLastCheckpoints(value: number | null | undefined): 1 | 2 | 3 {
  if (value === 1 || value === 2 || value === 3) {
    return value;
  }
  return 2;
}

export interface StudioNewReviewStartResult {
  reviewId: string;
  routePath: string;
  policyMode: StudioReviewPolicyMode;
