 */
export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
  if (!claimed) {
    const existing = await getReviewRun(env.DB, reviewId);
    if (existing?.status === 'running') {
      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
    }
    return;
  }

  let review: ReviewRunResponse | null = null;
  const manualFailAbortMonitor = startManualFailAbortMonitor(env, reviewId);
  try {
    review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return;
    }

    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
    if (!payload) {
      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
        errorCode: 'review_not_found',
        errorMessage: 'Review request payload no longer exists',
      });
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_failed',
        payload: {
          code: 'review_not_found',
          message: 'Review request payload no longer exists',
        },
      });
      return;
    }

    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
    const report = await executeReviewRun(env, review, payload, reviewContext, {
      ...options,
      abortSignal: manualFailAbortMonitor.signal,
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    await finalizeSuccessfulReview(env, reviewId, payload, report, {
      expectedAttemptCount: review.attemptCount,
    });
  } catch (error) {
    const message = formatReviewAnalysisError(error, {
      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    const attemptCount = latest?.attemptCount ?? review?.attemptCount ?? 0;

    const allowRetryScheduling = options?.allowRetryScheduling !== false;
    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
      await scheduleReviewRetry(env, reviewId, {
        attemptCount,
        message,
        reason: message.slice(0, 500),
        throwMessage: 'Review transient failure; retry requested',
      });
    }

    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
    await finalizeFailedReview(env, reviewId, {
      errorCode: finalErrorCode,
      message,
      contextAssemblyErrorCode,
    });
  } finally {
    manualFailAbortMonitor.stop();
  }
}

/**
 * Repeats inline review execution while the persisted state requests another retry cycle.
 */
export async function runReviewInlineWithRetries(
  env: Env,
  reviewId: string,
  maxCycles = 4,
  options?: ReviewRunExecutionOptions
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processReviewRun(env, reviewId, options);
    } catch {
      // Retry scheduling is inferred from persisted status.
    }

    const latest = await getReviewRun(env.DB, reviewId);
    if (!latest) {
      return;
    }
    if (latest.status !== 'queued') {
      return;
    }
    if (latest.error?.code !== 'retry_scheduled') {
      return;
    }
  }

  await finalizeInlineRetryExhaustion(env, reviewId);
}

import type { Env, ReviewReport, ReviewRunResponse } from '../../types.js';
import {
  appendReviewEvent,
  getReviewRun,
  getHighestFindingNumberForBranch,
  replaceReviewFindings,
  updateReviewRunStatus,
} from '../db.js';
import { stripSensitiveTokenFields } from '../db/reviews/shared.js';

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function readOptionalString(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function canFinalizeSuccessfulReview(review: ReviewRunResponse | null): boolean {
  if (!review) {
    return false;
  }
  if (review.status === 'running') {
    return true;
  }
  return review.status === 'queued' && review.error?.code === 'retry_scheduled';
}

async function persistSuccessfulReviewStatusIfCurrent(input: {
  db: D1Database;
  reviewId: string;
  report: ReviewReport;
  expectedAttemptCount?: number;
}): Promise<boolean> {
  const now = new Date().toISOString();
  const sql = [
    'UPDATE review_runs SET status = ?, updated_at = ?, report_json = ?, markdown_summary = ?, error_code = NULL, error_message = NULL, finished_at = COALESCE(finished_at, ?)',
    "WHERE id = ? AND (status = 'running' OR (status = 'queued' AND error_code = 'retry_scheduled'))",
  ];
  const values: Array<string | number | null> = [
    'succeeded',
    now,
    JSON.stringify(stripSensitiveTokenFields(input.report)),
    typeof input.report.markdownSummary === 'string'
      ? (stripSensitiveTokenFields(input.report.markdownSummary) as string)
      : input.report.markdownSummary,
    now,
    input.reviewId,
  ];

  if (typeof input.expectedAttemptCount === 'number') {
    sql.push(' AND attempt_count = ?');
    values.push(input.expectedAttemptCount);
  }

  const result = await input.db.prepare(sql.join(' ')).bind(...values).run();
  return (result.meta?.changes ?? 0) > 0;
}

/**
 * Persists successful review output, assigns branch-stable finding numbers, and emits completion events.
 */
export async function finalizeSuccessfulReview(
  env: Env,
  reviewId: string,
  payload: Record<string, unknown>,
  report: ReviewReport,
  options?: {
    expectedAttemptCount?: number;
  }
): Promise<void> {
  const latest = await getReviewRun(env.DB, reviewId);
  if (!latest || !canFinalizeSuccessfulReview(latest)) {
    return;
  }
  if (typeof options?.expectedAttemptCount === 'number' && latest.attemptCount !== options.expectedAttemptCount) {
    return;
  }

  const payloadRecord = asRecord(payload);
  const requestProvenance = asRecord(payloadRecord.provenance);
  const reviewRepo = readOptionalString(requestProvenance.repo);
  const reviewBranch = readOptionalString(requestProvenance.branch);
  if (!reviewRepo || !reviewBranch) {
    throw new Error('Review request payload missing required provenance.repo or provenance.branch.');
  }

  const findingSequenceStart = (await getHighestFindingNumberForBranch(env.DB, reviewRepo, reviewBranch)) + 1;
  const findingsWithSequence = report.findings.map((finding, index) => ({
    ...finding,
    sequence: findingSequenceStart + index,
  }));
  const reportWithSequence: ReviewReport = {
    ...report,
    findings: findingsWithSequence,
  };

  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_finalize_started',
    payload: {
      findingCount: report.findings.length,
    },
  });
  const persisted = await persistSuccessfulReviewStatusIfCurrent({
    db: env.DB,
    reviewId,
    report: reportWithSequence,
    expectedAttemptCount: options?.expectedAttemptCount,
  });
  if (!persisted) {
    return;
  }
  await replaceReviewFindings(env.DB, reviewId, findingsWithSequence, { startNumber: findingSequenceStart });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_findings_persisted',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_succeeded',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_succeeded',
    payload: {
      recommendation: report.summary.recommendation,
      findingCount: report.findings.length,
    },
  });
}

/**
 * Persists a terminal failed state and emits failure events, including context-assembly failures when applicable.
 */
export async function finalizeFailedReview(
  env: Env,
  reviewId: string,
  input: {
    errorCode: string;
    message: string;
    contextAssemblyErrorCode?: string | null;
  }
): Promise<void> {
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    errorCode: input.errorCode,
    errorMessage: input.message,
  });
  try {
    if (input.contextAssemblyErrorCode) {
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_context_assembly_failed',
        payload: {
          code: input.contextAssemblyErrorCode,
          message: input.message,
        },
      });
    }
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: input.errorCode,
        message: input.message,
      },
    });
  } catch {
    // Best-effort terminal event.
  }
}

