              maxBytesPerFile: { anyOf: [{ type: 'number' }, { type: 'null' }] },
              caseSensitive: { anyOf: [{ type: 'boolean' }, { type: 'null' }] },
            },
            required: ['path', 'paths', 'maxBytes', 'query', 'maxResults', 'maxBytesPerFile', 'caseSensitive'],
          },
          { type: 'null' },
        ],
      },
      summary: { anyOf: [{ type: 'string' }, { type: 'null' }] },
