                  },
                  required: ['severity', 'category', 'passType', 'locations', 'description', 'suggestedFix', 'failingScenario', 'evidence', 'guardGap'],
                },
              },
              summary: { type: 'string' },
              furtherPassesLowYield: { type: 'boolean' },
            },
            required: ['findings', 'summary', 'furtherPassesLowYield'],
