  if (separator <= 0 || separator >= trimmed.length - 2) {
    throw new Error('Invalid --checkpoint-range format. Use <start>..<end>.');
  }
  const start = trimmed.slice(0, separator).trim();
  const end = trimmed.slice(separator + 2).trim();
  if (!start || !end) {
    throw new Error('Invalid --checkpoint-range format. Use <start>..<end>.');
  }
  return { start, end };
}

