           started_at = COALESCE(started_at, ?),
           attempt_count = attempt_count + 1,
           error_code = NULL,
           error_message = NULL,
           updated_at = ?
       WHERE id = ? AND status IN ('queued', 'policy_approved')`
    )
    .bind(now, now, reviewId)
    .run();

  return (result.meta?.changes ?? 0) > 0;
}

export async function updateReviewRunStatus(
  db: D1Database,
  reviewId: string,
  status: ReviewRunStatus,
  options?: {
    report?: ReviewReport | null;
    markdownSummary?: string | null;
    errorCode?: string | null;
    errorMessage?: string | null;
    startedAt?: string | null;
    finishedAt?: string | null;
  }
): Promise<void> {
  const updates: string[] = ['status = ?', 'updated_at = ?'];
  const values: Array<string | null> = [status, new Date().toISOString()];

  if (options?.startedAt !== undefined) {
    updates.push('started_at = ?');
    values.push(options.startedAt);
  }
  if (options?.finishedAt !== undefined) {
    updates.push('finished_at = ?');
    values.push(options.finishedAt);
  }
  if (options?.report !== undefined) {
    updates.push('report_json = ?');
    values.push(options.report ? JSON.stringify(stripSensitiveTokenFields(options.report)) : null);
  }
  if (options?.markdownSummary !== undefined) {
    updates.push('markdown_summary = ?');
    values.push(typeof options.markdownSummary === 'string' ? (stripSensitiveTokenFields(options.markdownSummary) as string) : options.markdownSummary);
  }
  if (options?.errorCode !== undefined) {
    updates.push('error_code = ?');
    values.push(options.errorCode);
  }
  if (options?.errorMessage !== undefined) {
    updates.push('error_message = ?');
    values.push(options.errorMessage);
  }
  if (status === 'succeeded' || status === 'failed' || status === 'cancelled') {
    updates.push('finished_at = COALESCE(finished_at, ?)');
    values.push(new Date().toISOString());
  }

  values.push(reviewId);
  await db.prepare(`UPDATE review_runs SET ${updates.join(', ')} WHERE id = ?`).bind(...values).run();
}

export async function updateReviewRunPolicy(
  db: D1Database,
  reviewId: string,
  options: {
    derivedPolicy?: ReviewApprovedPolicy | null;
    approvedPolicy?: ReviewApprovedPolicy | null;
    approvedPolicySha256?: string | null;
  }
): Promise<void> {
  const updates: string[] = ['updated_at = ?'];
  const values: Array<string | null> = [new Date().toISOString()];

  if (options.derivedPolicy !== undefined) {
    updates.push('derived_policy_json = ?');
    values.push(options.derivedPolicy ? JSON.stringify(stripSensitiveTokenFields(options.derivedPolicy)) : null);
  }
  if (options.approvedPolicy !== undefined) {
    updates.push('approved_policy_json = ?');
    values.push(options.approvedPolicy ? JSON.stringify(stripSensitiveTokenFields(options.approvedPolicy)) : null);
  }
  if (options.approvedPolicySha256 !== undefined) {
    updates.push('approved_policy_sha256 = ?');
    values.push(options.approvedPolicySha256 ?? null);
  }

  values.push(reviewId);
  await db.prepare(`UPDATE review_runs SET ${updates.join(', ')} WHERE id = ?`).bind(...values).run();
}

export function reviewFailureGuidance(review: ReviewResponse): ReviewFailureGuidance | null {
  if (review.status !== 'failed') {
    return null;
  }

  const code = review.error?.code ?? 'review_execution_failed';
  const message = review.error?.message ?? 'Review execution failed.';

  if (code.startsWith('review_context_')) {
    return {
      headline: 'Review context could not be assembled.',
      details: message,
      actions: [
        'Re-run deploy/review after ensuring the checkpoint has readable Entire session context and commit diff patch data.',
        'Confirm branch fallback metadata was passed from preflight when checkpoint context is missing.',
      ],
    };
  }

  if (message.toLowerCase().includes('invalid output') || message.toLowerCase().includes('non-authoritative fallback')) {
    return {
      headline: 'Model output failed strict V2 validation.',
      details: message,
      actions: [
        'Retry the review to get a fresh model pass.',
        'If this persists, inspect review lifecycle events for validation failures and provider output formatting issues.',
      ],
    };
  }

  if (message.toLowerCase().includes('provider') || message.toLowerCase().includes('timed out')) {
    return {
      headline: 'The analysis provider failed during execution.',
      details: message,
      actions: [
        'Retry once provider availability is restored.',
        'If worker-to-worker fetch restrictions are mentioned, enable strictly public fetch or use a service binding for the agent endpoint.',
      ],
    };
  }

  return {
    headline: 'Review execution failed.',
    details: message,
    actions: ['Retry the review and inspect review event logs if the failure repeats.'],
  };
}

export function recommendationLabel(value: string | undefined): string {
  if (!value) {
    return 'unknown';
  }

  return value.replace('_', ' ');
}

export function dateTimeLabel(value: string | null): string {
  if (!value) {
    return 'n/a';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return date.toLocaleString();
}

