import type { Env, ReviewReport, ReviewRunResponse } from '../types.js';
import {
  appendReviewEvent,
  claimReviewRunForExecution,
  getReviewRun,
  getReviewRunRequestPayload,
  updateReviewRunStatus,
} from './db.js';
import { formatReviewAnalysisError } from './review-analysis.js';
import { ReviewContextAssemblyError } from './review-runner/cochange.js';
import { readOptionalString } from './review-runner/context-helpers.js';
import { assembleReviewContextBootstrap } from './review-runner/context.js';
import { executeReviewRun } from './review-runner/execution.js';
import { finalizeFailedReviewIfCurrent, finalizeSuccessfulReview } from './review-runner/finalization.js';
import { intentSummaryFromApprovedPolicy, runIntentSummarizationPrePass, summarizeReviewIntentPolicy } from './review-runner/intent-summary.js';
import {
  finalizeInlineRetryExhaustion,
  handleUnclaimedReviewRun,
  QueueRetryError,
  scheduleReviewRetryIfCurrent,
  shouldRetryReviewError,
} from './review-runner/retry.js';
import type { ReviewRunExecutionOptions } from './review-runner/shared.js';

export {
  intentSummaryFromApprovedPolicy,
  runIntentSummarizationPrePass,
  summarizeReviewIntentPolicy,
} from './review-runner/intent-summary.js';
export { shouldRetryReviewError } from './review-runner/retry.js';

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function isManuallyFailedReview(review: ReviewRunResponse | null): boolean {
  return review?.status === 'failed' && review.error?.code === 'review_execution_aborted';
}

async function loadLatestReviewUnlessManuallyFailed(env: Env, reviewId: string): Promise<ReviewRunResponse | null> {
  const latest = await getReviewRun(env.DB, reviewId);
  return isManuallyFailedReview(latest) ? null : latest;
}

function startManualFailAbortMonitor(env: Env, reviewId: string): { signal: AbortSignal; stop: () => void } {
  const controller = new AbortController();
  let stopped = false;
  let polling = false;
  let timer: ReturnType<typeof setInterval> | null = null;

  const stop = (): void => {
    if (stopped) {
      return;
    }
    stopped = true;
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  };

  const poll = async (): Promise<void> => {
    if (stopped || polling || controller.signal.aborted) {
      return;
    }
    polling = true;
    try {
      const latest = await getReviewRun(env.DB, reviewId);
      if (isManuallyFailedReview(latest)) {
        controller.abort();
        stop();
      }
    } finally {
      polling = false;
    }
  };

  timer = setInterval(() => {
    void poll();
  }, 250);
  void poll();

  return { signal: controller.signal, stop };
}

/**
 * Claims, executes, persists, and finalizes one review run.
 * This is the main orchestration boundary for review execution and retry scheduling.
 */
export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
  if (!claimed) {
    const existing = await getReviewRun(env.DB, reviewId);
    if (existing?.status === 'running') {
      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
    }
    return;
  }

  let review: ReviewRunResponse | null = null;
  const manualFailAbortMonitor = startManualFailAbortMonitor(env, reviewId);
  try {
    review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return;
    }

    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
    if (!payload) {
      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
        errorCode: 'review_not_found',
        errorMessage: 'Review request payload no longer exists',
      });
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_failed',
        payload: {
          code: 'review_not_found',
          message: 'Review request payload no longer exists',
        },
      });
      return;
    }

    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
    const report = await executeReviewRun(env, review, payload, reviewContext, {
      ...options,
      abortSignal: manualFailAbortMonitor.signal,
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    await finalizeSuccessfulReview(env, reviewId, payload, report, {
      expectedAttemptCount: review.attemptCount,
    });
  } catch (error) {
    const message = formatReviewAnalysisError(error, {
      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    const attemptCount = latest?.attemptCount ?? review?.attemptCount ?? 0;

    const allowRetryScheduling = options?.allowRetryScheduling !== false;
    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
      const retryScheduled = await scheduleReviewRetryIfCurrent(env, reviewId, {
        attemptCount,
        message,
        reason: message.slice(0, 500),
      });
      if (retryScheduled) {
        throw new QueueRetryError('Review transient failure; retry requested');
      }
    }

    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
    await finalizeFailedReviewIfCurrent(env, reviewId, {
      errorCode: finalErrorCode,
      message,
      contextAssemblyErrorCode,
      expectedAttemptCount: attemptCount,
    });
  } finally {
    manualFailAbortMonitor.stop();
  }
}

/**
 * Repeats inline review execution while the persisted state requests another retry cycle.
 */
export async function runReviewInlineWithRetries(
  env: Env,
  reviewId: string,
  maxCycles = 4,
  options?: ReviewRunExecutionOptions
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processReviewRun(env, reviewId, options);
    } catch {
      // Retry scheduling is inferred from persisted status.
    }

    const latest = await getReviewRun(env.DB, reviewId);
    if (!latest) {
      return;
    }
    if (latest.status !== 'queued') {
      return;
    }
    if (latest.error?.code !== 'retry_scheduled') {
      return;
    }
  }

  await finalizeInlineRetryExhaustion(env, reviewId);
}

import type { Env, ReviewRunResponse } from '../../types.js';
import {
  appendReviewEvent,
  getReviewRun,
  replaceReviewFindings,
  updateReviewRunStatus,
} from '../db.js';

export class QueueRetryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'QueueRetryError';
  }
}

const REVIEW_MAX_RETRIES = 2;
const DEFAULT_REVIEW_ATTEMPT_TIMEOUT_MS = 10 * 60 * 1000;
const REVIEW_STALE_GRACE_MS = 60 * 1000;

function parseTimeoutMs(value: string | undefined, fallback: number): number {
  if (typeof value !== 'string') {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }
  return parsed;
}

function toTimestampMs(value: string | null): number | null {
  if (typeof value !== 'string' || !value.trim()) {
    return null;
  }
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
}

export function transientReviewFailure(message: string): boolean {
  return /(d1|database is locked|sqlite_busy|temporarily unavailable|connection reset|timed out|timeout|aborted|fetch failed|network)/i.test(message);
}

/**
 * Moves a review back to queued state with a retry marker and clears any partial persisted output.
 */
export async function scheduleReviewRetry(
  env: Env,
  reviewId: string,
  input: {
    attemptCount: number;
    message: string;
    reason: string;
    extraPayload?: Record<string, unknown>;
    throwMessage?: string;
  }
): Promise<never> {
  await replaceReviewFindings(env.DB, reviewId, []);
  await updateReviewRunStatus(env.DB, reviewId, 'queued', {
    report: null,
    markdownSummary: null,
    startedAt: null,
    finishedAt: null,
    errorCode: 'retry_scheduled',
    errorMessage: input.message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_retry_scheduled',
    payload: {
      attemptCount: input.attemptCount,
      maxRetries: REVIEW_MAX_RETRIES,
      reason: input.reason,
      ...(input.extraPayload ?? {}),
    },
  });
  throw new QueueRetryError(input.throwMessage ?? 'Review retry requested');
}

/**
 * Schedules a retry only if the same running attempt is still current.
 * Returns false when another transition (for example manual fail) won the race.
 */
export async function scheduleReviewRetryIfCurrent(
  env: Env,
  reviewId: string,
  input: {
    attemptCount: number;
    message: string;
    reason: string;
    extraPayload?: Record<string, unknown>;
    throwMessage?: string;
  }
): Promise<boolean> {
  const now = new Date().toISOString();
  const transitioned = await env.DB
    .prepare(
      `UPDATE review_runs SET status = ?,
           updated_at = ?,
           started_at = NULL,
           finished_at = NULL,
           report_json = NULL,
           markdown_summary = NULL,
           error_code = ?,
           error_message = ?
       WHERE id = ? AND status = 'running' AND attempt_count = ?`
    )
    .bind('queued', now, 'retry_scheduled', input.message, reviewId, input.attemptCount)
    .run();

  if ((transitioned.meta?.changes ?? 0) === 0) {
    return false;
  }

  await replaceReviewFindings(env.DB, reviewId, []);
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_retry_scheduled',
    payload: {
      attemptCount: input.attemptCount,
      maxRetries: REVIEW_MAX_RETRIES,
      reason: input.reason,
      ...(input.extraPayload ?? {}),
    },
  });
  return true;
}

/**
 * Handles the case where a review could not be claimed because another worker may already be running it.
 * Detects stale-running reviews and either schedules a retry or marks them failed.
 */
export async function handleUnclaimedReviewRun(
  env: Env,
  reviewId: string,
  existing: ReviewRunResponse,
  allowRetryScheduling: boolean
): Promise<void> {
  if (existing.status !== 'running') {
    return;
  }

  const attemptTimeoutMs = parseTimeoutMs(env.ATTEMPT_TIMEOUT_MS, DEFAULT_REVIEW_ATTEMPT_TIMEOUT_MS);
  const staleThresholdMs = attemptTimeoutMs + REVIEW_STALE_GRACE_MS;
  const startedAtMs = toTimestampMs(existing.startedAt) ?? toTimestampMs(existing.updatedAt) ?? toTimestampMs(existing.createdAt);
  const staleForMs = startedAtMs === null ? null : Date.now() - startedAtMs;
  const isStale = typeof staleForMs === 'number' && staleForMs >= staleThresholdMs;
  if (!isStale) {
    throw new QueueRetryError('Review run is already running; defer redelivery');
  }

  const staleForSeconds = Math.floor((staleForMs ?? 0) / 1000);
  const message = `Review execution stalled in running state for ${staleForSeconds}s (timeout threshold ${Math.floor(staleThresholdMs / 1000)}s).`;
  const attemptCount = existing.attemptCount ?? 0;
  if (allowRetryScheduling && attemptCount <= REVIEW_MAX_RETRIES) {
    await scheduleReviewRetry(env, reviewId, {
      attemptCount,
      message,
      reason: 'stale_running_timeout',
      extraPayload: { staleForSeconds },
      throwMessage: 'Review stale-runn…85 chars truncated… []);
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    report: null,
    markdownSummary: null,
    errorCode: 'review_execution_timeout',
    errorMessage: message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_failed',
    payload: {
      code: 'review_execution_timeout',
      message,
    },
  });
}

/**
 * Final fallback when repeated inline retries leave the review stuck in queued/retry-scheduled state.
 */
export async function finalizeInlineRetryExhaustion(env: Env, reviewId: string): Promise<void> {
  const latest = await getReviewRun(env.DB, reviewId);
  if (latest?.status === 'queued' && latest.error?.code === 'retry_scheduled') {
    const message = `Review ${reviewId} remained queued after inline retries`;
    await replaceReviewFindings(env.DB, reviewId, []);
    await updateReviewRunStatus(env.DB, reviewId, 'failed', {
      report: null,
      markdownSummary: null,
      errorCode: 'review_execution_failed',
      errorMessage: message,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: 'review_execution_failed',
        message,
      },
    });
  }
}

export function shouldRetryReviewError(error: unknown): boolean {
  if (error instanceof QueueRetryError) {
    return true;
  }
  const message = error instanceof Error ? error.message : String(error);
  return transientReviewFailure(message);
}

