/**
 * Persists successful review output, assigns branch-stable finding numbers, and emits completion events.
 */
export async function finalizeSuccessfulReview(
  env: Env,
  reviewId: string,
  payload: Record<string, unknown>,
  report: ReviewReport,
  options?: {
    expectedAttemptCount?: number;
  }
): Promise<void> {
  const latest = await getReviewRun(env.DB, reviewId);
  if (!latest || !canFinalizeSuccessfulReview(latest)) {
    return;
  }
  if (typeof options?.expectedAttemptCount === 'number' && latest.attemptCount !== options.expectedAttemptCount) {
    return;
  }

  const payloadRecord = asRecord(payload);
  const requestProvenance = asRecord(payloadRecord.provenance);
  const reviewRepo = readOptionalString(requestProvenance.repo);
  const reviewBranch = readOptionalString(requestProvenance.branch);
  if (!reviewRepo || !reviewBranch) {
    throw new Error('Review request payload missing required provenance.repo or provenance.branch.');
  }

  const findingSequenceStart = (await getHighestFindingNumberForBranch(env.DB, reviewRepo, reviewBranch)) + 1;
  const findingsWithSequence = report.findings.map((finding, index) => ({
    ...finding,
    sequence: findingSequenceStart + index,
  }));
  const reportWithSequence: ReviewReport = {
    ...report,
    findings: findingsWithSequence,
  };

  const persisted = await persistSuccessfulReviewStatusIfCurrent({
    db: env.DB,
    reviewId,
    report: reportWithSequence,
    startedAt: latest.startedAt,
    expectedAttemptCount: options?.expectedAttemptCount,
  });
  if (!persisted) {
    return;
  }
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_finalize_started',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await replaceReviewFindings(env.DB, reviewId, findingsWithSequence, { startNumber: findingSequenceStart });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_findings_persisted',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_analysis_succeeded',
    payload: {
      findingCount: report.findings.length,
    },
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_succeeded',
    payload: {
      recommendation: report.summary.recommendation,
      findingCount: report.findings.length,
    },
  });
}

/**
 * Persists a terminal failed state and emits failure events, including context-assembly failures when applicable.
 */
export async function finalizeFailedReview(
  env: Env,
  reviewId: string,
  input: {
    errorCode: string;
    message: string;
    contextAssemblyErrorCode?: string | null;
  }
): Promise<void> {
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    errorCode: input.errorCode,
    errorMessage: input.message,
  });
  try {
    if (input.contextAssemblyErrorCode) {
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_context_assembly_failed',
        payload: {
          code: input.contextAssemblyErrorCode,
          message: input.message,
        },
      });
    }
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: input.errorCode,
        message: input.message,
      },
    });
  } catch {
    // Best-effort terminal event.
  }
}

/**
 * Persists a failed terminal state only if the same running attempt is still current.
 * Returns false when another transition (for example manual fail) won the race.
 */
export async function finalizeFailedReviewIfCurrent(
  env: Env,
  reviewId: string,
  input: {
    errorCode: string;
    message: string;
    contextAssemblyErrorCode?: string | null;
    expectedAttemptCount: number;
  }
): Promise<boolean> {
  const now = new Date().toISOString();
  const result = await env.DB
    .prepare(
      `UPDATE review_runs SET status = ?,
           updated_at = ?,
           error_code = ?,
           error_message = ?,
           finished_at = COALESCE(finished_at, ?)
       WHERE id = ? AND status = 'running' AND attempt_count = ?`
    )
    .bind('failed', now, input.errorCode, input.message, now, reviewId, input.expectedAttemptCount)
    .run();

  if ((result.meta?.changes ?? 0) === 0) {
    return false;
  }

  try {
    if (input.contextAssemblyErrorCode) {
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_context_assembly_failed',
        payload: {
          code: input.contextAssemblyErrorCode,
          message: input.message,

      finishedAt: null,
      errorCode: 'retry_scheduled',
      errorMessage: message,
    });
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_retry_scheduled',
      payload: {
        attemptCount: review.attemptCount,
        maxRetries,
        reason: 'manual_recovery',
        priorStatus: review.status,
        authMode: scopedGithubToken ? 'scoped_request_token' : 'local_cochange_only',
      },
    });
    await env.REVIEWS_QUEUE?.send(createReviewQueueMessage(reviewId, scopedGithubToken, openrouterApiKey));
    return {
      action: 'requeued',
      review: await getReviewRun(env.DB, reviewId),
    };
  }

  const missingTokenSuffix =
    !scopedGithubToken && !canRetryWithoutGithubToken
      ? ' No retry was scheduled because a fresh scoped GitHub token was not provided.'
      : '';
  const retriesExhaustedSuffix = review.attemptCount > maxRetries ? ' No retry was scheduled because max retry attempts were exhausted.' : '';
  const message = `Manual recovery stopped this review after it appeared stuck in ${review.status} state.${missingTokenSuffix}${retriesExhaustedSuffix}`;
  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
    report: null,
    markdownSummary: null,
    errorCode: 'review_execution_timeout',
    errorMessage: message,
  });
  await appendReviewEvent(env.DB, {
    reviewId,
    eventType: 'review_failed',
    payload: {
      code: 'review_execution_timeout',
      message,
      reason: 'manual_recovery',
    },
  });
  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

export async function manuallyFailReviewRun(
  env: Env,
  reviewId: string
): Promise<{ action: 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
  const review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return { action: 'failed', review: null };
  }

  if (review.status !== 'queued' && review.status !== 'running') {
    throw new Error(`Review is ${review.status}; only queued or running reviews can be failed manually.`);
  }

  const message =
    review.status === 'running'
      ? 'Review was manually marked failed while execution was still in progress. In-flight work may continue until the current attempt ends.'
      : 'Manual fail requested while review was queued.';

  const persisted = await persistManualFailIfCurrent({
    db: env.DB,
    reviewId,
    review: {
      status: review.status,
      attemptCount: review.attemptCount,
    },
    message,
  });
  if (persisted) {
    await appendReviewEvent(env.DB, {
      reviewId,
      eventType: 'review_failed',
      payload: {
        code: 'review_execution_aborted',
        message,
        reason: 'manual_fail',
        priorStatus: review.status,
      },
    });
  }

  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

