  const now = new Date().toISOString();
  const sql = [
    'UPDATE review_runs SET status = ?, updated_at = ?, started_at = COALESCE(started_at, ?), report_json = ?, markdown_summary = ?, error_code = NULL, error_message = NULL, finished_at = COALESCE(finished_at, ?)',
